// Bank soal susulan Electra Skill Academy.
//
// Latar belakang: bank soal lama (data/quiz-bank.js) hanya menjangkau 455 dari
// 1.117 modul, dan sebagian besar yang terjangkau cuma punya 1-2 soal. Akibatnya
// ratusan modul menyajikan soal kelistrikan umum yang tidak nyambung dengan
// videonya — keluhan yang masuk dari peserta.
//
// Berkas ini melengkapi bank lama, TIDAK menggantikannya. Saat kuis dirender,
// isi QUIZ_BANK[code] dan QUIZ_BANK_EXT[code] digabung.
//
// Aturan penulisan soal di sini:
//   1. Setiap soal harus bisa dijawab dari materi modulnya sendiri.
//   2. Tidak ada soal yang merujuk gambar/diagram kecuali gambarnya disertakan.
//   3. Setiap soal punya `hint` yang mengarahkan cara berpikir TANPA menyebut
//      jawabannya, dan `explain` yang menjelaskan alasannya.
//   4. Opsi pengecoh harus masuk akal — bukan opsi kosong seperti "Semua benar".
//
// Dijaga oleh tests/quiz-coverage.test.mjs dan tests/quiz-integrity.test.mjs.

window.QUIZ_BANK_EXT = {

  // ===================================================================
  // S9 · Technical Sales & Business Academy (kode 3I / 4I / 5I / 6I)
  // ===================================================================

  '3I.01': [
    {type:'pg',q:'Dalam struktur ketenagalistrikan Indonesia, PLN memegang peran sebagai pemegang izin usaha penyediaan tenaga listrik untuk kepentingan umum. Istilah yang dipakai untuk izin ini adalah…',opts:['IUPTL (Izin Usaha Penyediaan Tenaga Listrik)','IUJPTL (Izin Usaha Jasa Penunjang Tenaga Listrik)','SLO (Sertifikat Laik Operasi)','SBU (Sertifikat Badan Usaha)'],a:0,explain:'IUPTL adalah izin untuk menyediakan tenaga listrik (membangkitkan, mentransmisikan, mendistribusikan, menjual). IUJPTL adalah izin untuk usaha jasa penunjang seperti konsultansi dan pemasangan. SLO adalah sertifikat kelaikan instalasi, dan SBU adalah sertifikat kualifikasi badan usaha — ketiganya bukan izin penyediaan listrik.',hint:'Bedakan antara izin untuk MENYEDIAKAN listrik dan izin untuk memberi JASA PENUNJANG bagi penyedia listrik.'},
    {type:'pg',q:'Seorang technical sales perlu tahu siapa pembeli terbesar produk elektrikal tegangan menengah di Indonesia. Segmen mana yang paling tepat disebut sebagai penggerak utama permintaan panel dan switchgear MV?',opts:['Rumah tangga perkotaan','PLN, industri manufaktur, dan pengembang properti/kawasan','Toko ritel elektronik','Usaha mikro dan kecil'],a:1,explain:'Produk tegangan menengah (20 kV) dipakai pada gardu distribusi, pabrik, gedung tinggi, dan kawasan industri. Pembelinya adalah PLN, industri manufaktur, serta pengembang properti dan kawasan. Rumah tangga dan ritel memakai tegangan rendah, sehingga bukan pasar untuk MV switchgear.',hint:'Tanyakan pada dirimu: siapa yang instalasinya benar-benar beroperasi di tegangan 20 kV, bukan 220 V?'},
    {type:'pg',q:'Apa perbedaan mendasar antara pasar B2B dan B2C yang paling memengaruhi cara menjual produk elektrikal?',opts:['Harga B2B selalu lebih murah','Keputusan beli B2B melibatkan banyak pihak dan siklusnya panjang','Produk B2B tidak perlu bergaransi','Pasar B2B tidak terpengaruh regulasi'],a:1,explain:'Di B2B, pembelian melewati banyak peran — pengguna teknis, engineering, procurement, keuangan, hingga manajemen — sehingga siklus penjualan berbulan-bulan dan butuh dokumen teknis serta justifikasi biaya. Harga B2B tidak otomatis lebih murah, garansi justru lebih ketat, dan regulasi (SNI, TKDN) sangat menentukan.',hint:'Pikirkan berapa banyak orang yang harus setuju sebelum sebuah pabrik membeli trafo, dibandingkan saat kamu membeli lampu.'},
    {type:'pg',q:'Istilah "captive power" dalam bisnis kelistrikan merujuk pada…',opts:['Listrik yang dibangkitkan sendiri oleh industri untuk kebutuhannya sendiri','Listrik yang dijual PLN ke pelanggan rumah tangga','Daya cadangan yang disimpan di baterai','Daya yang hilang di saluran transmisi'],a:0,explain:'Captive power adalah pembangkitan listrik oleh suatu entitas untuk memenuhi kebutuhannya sendiri, misalnya pabrik dengan pembangkit sendiri. Ini pasar penting bagi penjual genset, trafo, dan panel. Listrik yang dijual ke pelanggan umum disebut listrik publik, dan kehilangan di saluran disebut losses.',hint:'Kata "captive" berarti tertawan atau terikat — listriknya tidak dilepas ke jaringan umum.'},
    {type:'pg',q:'Dalam rantai nilai ketenagalistrikan, urutan yang benar dari hulu ke hilir adalah…',opts:['Distribusi → Transmisi → Pembangkitan → Pelanggan','Pembangkitan → Transmisi → Distribusi → Pelanggan','Transmisi → Pembangkitan → Pelanggan → Distribusi','Pembangkitan → Distribusi → Transmisi → Pelanggan'],a:1,explain:'Listrik dibangkitkan di pembangkit, dinaikkan tegangannya dan disalurkan jarak jauh lewat transmisi (150/500 kV), diturunkan dan disebar lewat distribusi (20 kV dan 380/220 V), lalu sampai ke pelanggan. Memahami urutan ini menentukan produk apa yang relevan untuk tiap segmen pelanggan.',hint:'Ikuti perjalanan satu elektron dari pembangkit sampai stopkontak, dan perhatikan di titik mana tegangan dinaikkan lalu diturunkan.'},
    {type:'pg',q:'Mengapa seorang technical sales wajib memahami regulasi seperti Permen ESDM dan aturan TKDN, bukan sekadar spesifikasi produk?',opts:['Karena regulasi menentukan harga jual eceran produk','Karena regulasi menentukan produk mana yang boleh dipakai dan menang tender','Karena regulasi mengatur komisi penjualan','Karena regulasi menggantikan kebutuhan uji mutu produk'],a:1,explain:'Regulasi menentukan persyaratan yang harus dipenuhi agar produk bisa dipasang dan lolos tender — misalnya wajib SNI, batas minimum TKDN, atau standar yang diacu PLN. Produk yang unggul secara teknis tetap gugur bila tidak memenuhi syarat regulasi. Regulasi ini tidak mengatur komisi dan tidak menghapus kewajiban uji mutu.',hint:'Pikirkan apa yang membuat penawaran dinyatakan gugur di tahap evaluasi administrasi, sebelum harga dilihat sama sekali.'}
  ],

  '3I.02': [
    {type:'pg',q:'Fungsi utama MV switchgear (switchgear tegangan menengah) pada sebuah gardu distribusi adalah…',opts:['Menaikkan tegangan dari 20 kV ke 150 kV','Menghubungkan, memutus, dan melindungi rangkaian tegangan menengah','Mengubah arus bolak-balik menjadi arus searah','Menyimpan energi listrik saat beban rendah'],a:1,explain:'MV switchgear berisi pemutus (circuit breaker), pemisah, trafo ukur, dan relai proteksi yang berfungsi menghubungkan, memutus, dan melindungi rangkaian 20 kV. Menaikkan tegangan adalah tugas trafo step-up, konversi AC-DC adalah tugas rectifier, dan penyimpanan energi adalah tugas baterai.',hint:'Perhatikan arti kata "switch" pada namanya — apa yang dilakukan alat ini terhadap aliran daya?'},
    {type:'pg',q:'Pada spesifikasi kabel NYY 4×25 mm², angka 25 mm² menunjukkan…',opts:['Diameter luar kabel','Luas penampang penghantar tiap inti','Tebal isolasi kabel','Panjang kabel per gulungan'],a:1,explain:'Angka dalam mm² pada penamaan kabel menyatakan luas penampang penghantar tiap inti, yang menentukan kemampuan hantar arus (KHA). Angka 4 menunjukkan jumlah inti. Diameter luar dan tebal isolasi dinyatakan terpisah dalam lembar data, dan panjang tidak pernah masuk ke kode penamaan.',hint:'Satuannya mm² — itu satuan luas, bukan panjang atau tebal. Besaran apa pada penghantar yang diukur dengan luas?'},
    {type:'pg',q:'Perbedaan utama antara kabel NYY dan NYFGbY terletak pada…',opts:['NYFGbY punya perisai/armor kawat baja sehingga tahan tekanan mekanis','NYY hanya untuk arus searah','NYFGbY tidak punya isolasi','NYY hanya tersedia satu inti'],a:0,explain:'Huruf Gb pada NYFGbY menunjukkan adanya perisai kawat baja (armor), sehingga kabel ini tahan tekanan mekanis dan cocok ditanam langsung di tanah tanpa pipa pelindung. NYY tanpa armor umumnya ditanam dengan pelindung tambahan. Keduanya berisolasi PVC dan tersedia dalam berbagai jumlah inti serta dipakai untuk arus bolak-balik.',hint:'Bedah kode hurufnya: satu huruf di tengah menandakan lapisan pelindung logam tambahan.'},
    {type:'pg',q:'Sebuah trafo distribusi bertanda 630 kVA, 20 kV/400 V. Angka 630 kVA menyatakan…',opts:['Daya nyata yang terpakai beban','Daya semu maksimum yang boleh dialirkan trafo','Energi yang bisa disimpan trafo','Rugi daya trafo saat beban penuh'],a:1,explain:'Rating trafo dinyatakan dalam kVA karena trafo dibatasi oleh arus (pemanasan belitan) dan tegangan, bukan oleh faktor daya beban. 630 kVA adalah daya semu maksimum yang boleh dialirkan. Daya nyata yang terpakai bergantung faktor daya beban, trafo tidak menyimpan energi, dan rugi daya jauh lebih kecil dari rating.',hint:'Perhatikan mengapa satuannya kVA dan bukan kW — besaran mana yang tidak bergantung pada faktor daya beban?'},
    {type:'pg',q:'Panel MDP (Main Distribution Panel) pada instalasi gedung berfungsi sebagai…',opts:['Panel utama yang menerima suplai dan membaginya ke panel-panel cabang','Panel kendali motor tunggal','Panel pengukuran energi milik PLN','Panel penerangan darurat'],a:0,explain:'MDP adalah panel distribusi utama yang menerima suplai dari trafo atau PLN lalu membaginya ke sub-panel (SDP) dan panel cabang. Panel kendali motor disebut MCC, panel pengukuran PLN disebut panel meter, dan penerangan darurat punya panel tersendiri.',hint:'Kata kuncinya "Main" dan "Distribution" — panel ini berada di posisi mana dalam urutan pembagian daya?'},
    {type:'pg',q:'Saat menawarkan panel listrik ke pelanggan industri, tingkat proteksi IP54 pada enclosure berarti panel tersebut…',opts:['Tahan ledakan di area gas','Terlindung dari debu dalam jumlah terbatas dan cipratan air dari segala arah','Tahan terendam air sedalam 1 meter','Tahan suhu sampai 54 °C'],a:1,explain:'Pada kode IP, digit pertama menyatakan perlindungan terhadap benda padat/debu dan digit kedua terhadap air. IP54 berarti terlindung dari debu dalam jumlah terbatas (5) dan dari cipratan air segala arah (4). Tahan terendam membutuhkan digit kedua 7, ketahanan ledakan diatur standar Ex, dan suhu tidak dinyatakan dalam kode IP.',hint:'Kode IP punya dua digit dengan arti berbeda: satu untuk benda padat, satu untuk air. Angka 54 bukan berarti 54 derajat.'}
  ],

  '3I.03': [
    {type:'pg',q:'Single Line Diagram (SLD) menggambarkan sistem tiga fasa dengan satu garis. Tujuan utama penyederhanaan ini adalah…',opts:['Menghemat tinta saat pencetakan','Menampilkan hubungan antar-komponen dan aliran daya tanpa detail tiap fasa','Menyembunyikan informasi teknis dari kompetitor','Menggantikan kebutuhan gambar wiring detail'],a:1,explain:'SLD menyederhanakan tiga fasa menjadi satu garis agar hubungan antar-peralatan, proteksi, dan aliran daya terbaca jelas dalam satu lembar. SLD tidak menggantikan gambar wiring atau skema kendali yang tetap diperlukan saat pemasangan.',hint:'Pikirkan apa yang ingin dilihat seorang engineer dalam sekali pandang: susunan sistem, atau sambungan tiap kawat?'},
    {type:'pg',q:'Pada SLD, simbol lingkaran dengan dua belitan yang bersinggungan umumnya melambangkan…',opts:['Transformator','Pemutus tenaga','Kapasitor bank','Penyearah'],a:0,explain:'Dua lingkaran atau belitan yang bersinggungan adalah simbol baku transformator, menggambarkan kopling magnetik antara belitan primer dan sekunder. Pemutus tenaga digambarkan sebagai kotak atau silang pada garis, kapasitor sebagai dua garis sejajar, dan penyearah sebagai kotak dengan simbol dioda.',hint:'Simbolnya meniru bentuk fisik alatnya: dua kumparan yang berdekatan dan saling berinteraksi lewat medan magnet.'},
    {type:'pg',q:'Dalam spesifikasi teknis tender, istilah "breaking capacity" atau Icu pada circuit breaker menyatakan…',opts:['Arus nominal yang boleh mengalir terus-menerus','Arus hubung singkat maksimum yang mampu diputus dengan aman','Tegangan kerja maksimum','Jumlah operasi buka-tutup seumur alat'],a:1,explain:'Icu (ultimate breaking capacity) adalah arus hubung singkat maksimum yang sanggup diputus pemutus tanpa rusak. Arus yang boleh mengalir terus-menerus adalah In (arus nominal). Salah memilih Icu berakibat pemutus gagal memutus gangguan dan bisa meledak.',hint:'Kata "breaking" mengacu pada kondisi paling ekstrem yang harus diputus, bukan kondisi kerja harian.'},
    {type:'pg',q:'Seorang sales menerima spesifikasi "Busbar: Cu, 1250 A, 50 kA/1 s". Angka 50 kA/1 s menyatakan…',opts:['Arus kerja normal busbar','Kemampuan busbar menahan arus hubung singkat selama 1 detik','Kapasitas energi yang tersimpan','Kecepatan operasi pemutus'],a:1,explain:'Nilai 50 kA/1 s adalah short-time withstand current: busbar harus sanggup menahan gaya elektromagnetik dan panas akibat arus hubung singkat 50 kA selama 1 detik sampai proteksi bekerja. Arus kerja normalnya adalah 1250 A.',hint:'Ada dua angka arus dalam spesifikasi itu. Yang satu untuk kondisi normal, yang jauh lebih besar untuk kondisi apa?'},
    {type:'pg',q:'Kenapa seorang technical sales perlu bisa membaca SLD milik calon pelanggan sebelum menawarkan produk?',opts:['Agar bisa menaikkan harga penawaran','Agar bisa mengusulkan produk dengan rating dan titik pasang yang benar','Karena SLD wajib dilampirkan pada faktur pajak','Agar bisa melewati proses uji mutu'],a:1,explain:'Dari SLD terbaca tegangan sistem, rating arus, tingkat hubung singkat, dan posisi peralatan. Tanpa itu, usulan produk bisa salah rating atau salah titik pasang sehingga penawaran gugur secara teknis. SLD tidak ada hubungannya dengan faktur pajak maupun pembebasan uji mutu.',hint:'Penawaran bisa gugur bukan karena harga, tapi karena barangnya tidak cocok dengan sistem pelanggan. Informasi itu ada di mana?'},
    {type:'pg',q:'Istilah "incoming" dan "outgoing" pada panel distribusi merujuk pada…',opts:['Jadwal masuk dan keluar operator','Kubikel penerima suplai dan kubikel penyalur ke beban','Arus masuk dan arus bocor','Tegangan primer dan tegangan induksi'],a:1,explain:'Incoming adalah kubikel atau kompartemen yang menerima suplai daya masuk ke panel, sedangkan outgoing menyalurkan daya keluar ke beban atau panel berikutnya. Membedakan keduanya penting agar rating dan proteksi yang ditawarkan tepat sasaran.',hint:'Lihat arah aliran daya terhadap panel itu sendiri: yang menuju masuk, dan yang meninggalkan panel.'}
  ],

  '3I.04': [
    {type:'pg',q:'LPSE dalam pengadaan barang/jasa pemerintah adalah…',opts:['Lembaga yang menetapkan harga satuan nasional','Layanan Pengadaan Secara Elektronik, sistem tempat tender diumumkan dan diproses','Lembaga sertifikasi produk elektrikal','Sistem pembayaran pajak kontraktor'],a:1,explain:'LPSE adalah Layanan Pengadaan Secara Elektronik, yaitu unit dan sistem yang memfasilitasi pengadaan secara daring, termasuk pengumuman tender, pemasukan penawaran, dan evaluasi. Penetapan harga satuan, sertifikasi produk, dan perpajakan ditangani lembaga lain.',hint:'Uraikan singkatannya — setiap hurufnya menjelaskan fungsinya sebagai sarana, bukan sebagai lembaga penilai.'},
    {type:'pg',q:'Pada tender pemerintah, dokumen yang memuat persyaratan administrasi, teknis, dan harga yang harus dipenuhi peserta disebut…',opts:['Dokumen pemilihan (dokumen tender)','Berita acara serah terima','Surat perintah kerja','Laporan akhir proyek'],a:0,explain:'Dokumen pemilihan berisi seluruh syarat yang harus dipenuhi peserta: persyaratan administrasi, spesifikasi teknis, dan tata cara penawaran harga. SPK terbit setelah pemenang ditetapkan, sedangkan berita acara serah terima dan laporan akhir muncul di tahap pelaksanaan.',hint:'Cari dokumen yang terbit paling awal — yang dibaca peserta sebelum menyusun penawaran.'},
    {type:'pg',q:'Evaluasi penawaran pada tender umumnya dilakukan berurutan. Urutan yang benar adalah…',opts:['Harga → teknis → administrasi','Administrasi → teknis → harga','Teknis → harga → administrasi','Harga → administrasi → teknis'],a:1,explain:'Evaluasi dimulai dari kelengkapan administrasi, lalu kesesuaian teknis, baru kewajaran harga. Peserta yang gugur di administrasi tidak dievaluasi lebih lanjut meski harganya termurah — inilah sebabnya kelengkapan dokumen sama pentingnya dengan harga.',hint:'Penawaran termurah pun tidak dilihat kalau satu berkas tidak lengkap. Tahap mana yang menyaring lebih dulu?'},
    {type:'pg',q:'TKDN yang dipersyaratkan dalam tender proyek ketenagalistrikan mengukur…',opts:['Tingkat keuntungan penyedia','Besarnya komponen dalam negeri pada barang/jasa yang ditawarkan','Tingkat kesulitan teknis pekerjaan','Jumlah tenaga kerja asing yang dipakai'],a:1,explain:'TKDN (Tingkat Komponen Dalam Negeri) mengukur porsi komponen dalam negeri pada barang dan jasa yang ditawarkan, dihitung dari biaya material, tenaga kerja, dan alat kerja dalam negeri. Nilainya memberi preferensi dalam evaluasi dan sering menjadi syarat wajib di proyek pemerintah dan PLN.',hint:'Baca kepanjangannya secara harfiah — yang diukur adalah asal komponennya, bukan sulit atau mudahnya pekerjaan.'},
    {type:'pg',q:'Jaminan penawaran (bid bond) dalam tender berfungsi untuk…',opts:['Menjamin peserta tidak mengundurkan diri setelah ditetapkan menang','Menjamin mutu barang selama masa garansi','Membayar uang muka kepada penyedia','Menutup kekurangan pembayaran pajak'],a:0,explain:'Jaminan penawaran mengikat peserta agar tidak menarik penawarannya atau menolak penetapan sebagai pemenang. Mutu selama garansi dijamin oleh jaminan pemeliharaan, uang muka dijamin jaminan uang muka, dan pajak bukan objek jaminan tender.',hint:'Cocokkan tiap jenis jaminan dengan tahapan proyeknya — bid bond melekat pada tahap paling awal.'},
    {type:'pg',q:'Metode e-Procurement memberi manfaat terbesar dalam hal…',opts:['Menjamin harga penawaran selalu paling murah','Meningkatkan transparansi dan jejak audit proses pengadaan','Menghapus kebutuhan evaluasi teknis','Menjamin proyek selesai tepat waktu'],a:1,explain:'Pengadaan elektronik membuat pengumuman, pemasukan dokumen, dan hasil evaluasi tercatat serta dapat diaudit, sehingga mempersempit ruang praktik tidak sehat. E-Procurement tidak menjamin harga termurah, tidak menghapus evaluasi teknis, dan tidak menjamin ketepatan waktu pelaksanaan.',hint:'Fokus pada perubahan yang dibawa sistem daring terhadap PROSES, bukan terhadap hasil akhir proyek.'}
  ],

  '3I.05': [
    {type:'pg',q:'Bill of Quantity (BOQ) dalam penawaran proyek elektrikal berisi…',opts:['Rincian item pekerjaan/material beserta volume dan satuannya','Riwayat pembayaran pelanggan','Daftar karyawan yang ditugaskan','Jadwal pemeliharaan tahunan'],a:0,explain:'BOQ adalah daftar rinci item pekerjaan dan material lengkap dengan volume, satuan, harga satuan, dan jumlah. BOQ menjadi dasar perhitungan nilai penawaran sekaligus dasar penagihan progres. Daftar personel, riwayat pembayaran, dan jadwal pemeliharaan adalah dokumen terpisah.',hint:'Perhatikan kata "quantity" — yang didaftar adalah sesuatu yang bisa dihitung volumenya.'},
    {type:'pg',q:'Harga satuan pekerjaan dalam BOQ idealnya sudah mencakup…',opts:['Hanya harga beli material','Material, upah, alat, overhead, dan keuntungan','Hanya upah tenaga kerja','Hanya biaya transportasi'],a:1,explain:'Harga satuan yang sehat menutup seluruh biaya untuk menyelesaikan satu satuan pekerjaan: material, upah, peralatan, overhead, serta margin keuntungan. Menghitung hanya harga beli material adalah penyebab paling umum penawaran merugi saat dikerjakan.',hint:'Bayangkan semua uang yang benar-benar keluar untuk menyelesaikan satu unit pekerjaan, lalu tanyakan dari mana untungnya datang.'},
    {type:'pg',q:'Dalam penawaran, istilah "lump sum" berarti…',opts:['Harga dihitung ulang sesuai volume terpasang','Harga borongan tetap untuk lingkup pekerjaan yang disepakati','Harga hanya mencakup material','Pembayaran dilakukan di muka seluruhnya'],a:1,explain:'Kontrak lump sum menetapkan harga total tetap untuk lingkup pekerjaan yang disepakati; risiko selisih volume ditanggung penyedia. Kebalikannya adalah kontrak harga satuan (unit price) yang dihitung ulang sesuai volume terpasang. Lump sum tidak menentukan cara pembayaran.',hint:'Pertanyaan kuncinya: kalau volume terpasang ternyata lebih besar dari perkiraan, siapa yang menanggung selisihnya?'},
    {type:'pg',q:'Sebuah penawaran mencantumkan harga Rp 100 juta dengan keterangan "belum termasuk PPN". Jika PPN 11%, total yang dibayar pelanggan adalah…',opts:['Rp 100.000.000','Rp 111.000.000','Rp 89.000.000','Rp 110.000.000'],a:1,explain:'PPN 11% dihitung dari dasar pengenaan pajak, yaitu Rp 100 juta × 11% = Rp 11 juta, sehingga total menjadi Rp 111 juta. Kesalahan lazim adalah menganggap harga sudah termasuk PPN, yang membuat margin tergerus saat penagihan.',calc:'Total = Harga × (1 + tarif PPN)',hint:'Hitung nilai pajaknya lebih dulu dari harga dasar, baru tambahkan — jangan mengurangkan dari harga yang tertera.'},
    {type:'pg',q:'Apa risiko terbesar bila volume dalam BOQ dihitung terlalu rendah?',opts:['Pelanggan membatalkan pembayaran pajak','Penawaran terlihat murah tetapi merugi saat pelaksanaan','Penawaran otomatis gugur administrasi','Barang tidak bisa dikirim'],a:1,explain:'Volume yang kurang membuat nilai penawaran tampak kompetitif, tetapi kekurangan material dan pekerjaan tetap harus dipenuhi saat pelaksanaan dengan biaya penyedia — terutama pada kontrak lump sum. Inilah penyebab klasik proyek menang tender tapi rugi.',hint:'Pikirkan apa yang terjadi di lapangan setelah kontrak diteken, saat kebutuhan sebenarnya ternyata lebih besar dari yang ditawarkan.'},
    {type:'pg',q:'Istilah "margin kotor" (gross margin) pada penawaran dihitung sebagai…',opts:['Harga jual dikurangi seluruh pajak','(Harga jual − harga pokok) dibagi harga jual','Harga pokok dibagi harga jual','Harga jual dikurangi gaji direksi'],a:1,explain:'Margin kotor adalah selisih harga jual dan harga pokok penjualan, dinyatakan sebagai persentase terhadap harga jual. Rasio ini dipakai menilai apakah penawaran masih sehat sebelum dikurangi biaya operasional perusahaan.',calc:'Margin kotor (%) = (Harga jual − HPP) ÷ Harga jual × 100%',hint:'Perhatikan pembaginya: margin dinyatakan terhadap harga jual, bukan terhadap harga pokok.'}
  ],

  '3I.06': [
    {type:'pg',q:'Dalam customer profiling, apa yang membedakan pola pembelian PLN dibandingkan pelanggan industri swasta?',opts:['PLN membeli tanpa spesifikasi teknis','PLN terikat proses pengadaan formal, standar internal, dan daftar penyedia terdaftar','PLN tidak pernah melakukan tender','PLN hanya membeli produk impor'],a:1,explain:'Sebagai BUMN, PLN terikat aturan pengadaan formal, standar internal (SPLN), dan sistem penyedia terdaftar. Industri swasta lebih fleksibel dan lebih menekankan kecepatan serta total biaya kepemilikan. Memahami perbedaan ini menentukan pendekatan penjualan.',hint:'Pikirkan pembeli mana yang keputusannya harus bisa dipertanggungjawabkan secara administratif kepada auditor.'},
    {type:'pg',q:'Istilah "decision making unit" (DMU) dalam penjualan B2B merujuk pada…',opts:['Satu orang yang menandatangani kontrak','Kumpulan peran yang memengaruhi keputusan beli, dari pengguna sampai penyetuju anggaran','Unit produksi di pabrik pelanggan','Sistem perangkat lunak pengambil keputusan'],a:1,explain:'DMU mencakup pengguna teknis, engineering, procurement, keuangan, dan manajemen yang menyetujui anggaran. Menjual hanya ke satu peran membuat penawaran mandek karena kebutuhan peran lain tidak terjawab.',hint:'Kalau hanya satu orang yang perlu diyakinkan, mengapa siklus penjualan B2B bisa berbulan-bulan?'},
    {type:'pg',q:'Seorang kontraktor listrik sebagai pelanggan umumnya paling sensitif terhadap…',opts:['Harga dan ketersediaan barang sesuai jadwal proyek','Warna kemasan produk','Jumlah iklan produk','Lokasi kantor pusat penyedia'],a:0,explain:'Kontraktor bekerja dengan margin tipis dan jadwal ketat, sehingga harga kompetitif dan kepastian pengiriman menentukan keputusannya. Berbeda dengan pemilik pabrik yang lebih menimbang keandalan jangka panjang dan layanan purnajual.',hint:'Pikirkan apa yang paling cepat merugikan kontraktor bila meleset: sedikit selisih harga, atau barang telat sehingga proyeknya kena denda?'},
    {type:'pg',q:'Pendekatan yang paling tepat saat menghadapi developer kawasan industri yang sedang merencanakan pembangunan adalah…',opts:['Menawarkan diskon terbesar sejak awal','Terlibat sejak tahap desain agar produk masuk dalam spesifikasi proyek','Menunggu tender diumumkan','Menawarkan produk apa adanya lewat surel massal'],a:1,explain:'Masuk di tahap desain memungkinkan produk kita tercantum dalam spesifikasi teknis proyek, yang jauh lebih menentukan daripada bersaing harga saat tender sudah terbit. Strategi ini dikenal sebagai specification selling.',hint:'Pada tahap mana spesifikasi proyek masih bisa dipengaruhi — sebelum atau sesudah tender diumumkan?'},
    {type:'pg',q:'Informasi paling berguna untuk menilai potensi jangka panjang seorang pelanggan industri adalah…',opts:['Rencana ekspansi kapasitas produksi dan usia instalasi listriknya','Jumlah karyawan bagian pemasaran','Warna logo perusahaan','Jumlah pengikut media sosialnya'],a:0,explain:'Rencana ekspansi menandakan kebutuhan daya baru, sedangkan instalasi yang sudah tua menandakan kebutuhan penggantian dan pemeliharaan. Keduanya adalah sumber kebutuhan nyata akan panel, trafo, dan kabel.',hint:'Cari sinyal yang benar-benar menciptakan kebutuhan listrik baru atau penggantian peralatan.'},
    {type:'pg',q:'Segmentasi pelanggan yang baik untuk technical sales elektrikal sebaiknya didasarkan pada…',opts:['Abjad nama perusahaan','Kebutuhan teknis, kapasitas daya, dan pola pengadaannya','Jarak kantor dari rumah sales','Usia pemilik perusahaan'],a:1,explain:'Segmentasi berdasarkan kebutuhan teknis, kapasitas daya terpasang, dan cara mereka melakukan pengadaan menghasilkan kelompok dengan pendekatan penjualan yang benar-benar berbeda, sehingga sumber daya penjualan bisa dialokasikan efektif.',hint:'Segmentasi berguna bila tiap kelompok menuntut CARA MENJUAL yang berbeda. Faktor mana yang menentukan itu?'}
  ],

  // ===================================================================
  // S10 · Solar PV (PLTS) Academy (kode 3J / 4J / 5J / 6J)
  // ===================================================================

  '3J.01': [
    {type:'pg',q:'Pada kurva I-V sebuah modul surya, titik yang menghasilkan daya keluaran terbesar disebut…',opts:['Short circuit point (Isc)','Maximum Power Point (MPP)','Open circuit point (Voc)','Titik nol kurva'],a:1,explain:'Daya adalah hasil kali arus dan tegangan. Di Isc tegangannya nol dan di Voc arusnya nol, sehingga daya di kedua titik itu nol. Daya maksimum berada di antara keduanya, yaitu MPP, dan inilah titik yang dikejar inverter lewat algoritma MPPT.',hint:'Daya = arus × tegangan. Cek berapa nilai daya di kedua ujung kurva sebelum menebak titik tengahnya.'},
    {type:'pg',q:'Yang terjadi pada arus hubung singkat (Isc) sebuah modul surya ketika intensitas radiasi matahari naik adalah…',opts:['Naik hampir sebanding dengan radiasi','Turun sebanding dengan radiasi','Tetap, tidak dipengaruhi radiasi','Naik hanya bila suhu ikut turun'],a:0,explain:'Jumlah pasangan elektron-hole yang terbentuk sebanding dengan jumlah foton yang datang, sehingga Isc naik hampir linier terhadap iradiansi. Tegangan Voc jauh lebih sedikit terpengaruh radiasi, tetapi sangat dipengaruhi suhu.',hint:'Pikirkan apa yang menghasilkan arus pada sel surya: makin banyak foton datang, makin banyak apa yang terbentuk?'},
    {type:'pg',q:'Kenaikan suhu sel surya pada umumnya menyebabkan…',opts:['Tegangan Voc turun sehingga daya keluaran berkurang','Tegangan Voc naik sehingga daya bertambah','Arus dan tegangan sama-sama naik tajam','Efisiensi modul meningkat'],a:0,explain:'Koefisien suhu modul silikon untuk tegangan bernilai negatif (sekitar −0,3%/°C), sehingga Voc dan daya turun saat sel memanas. Arus sedikit naik, tetapi kenaikannya tidak menutup penurunan tegangan. Karena itu ventilasi di belakang modul penting.',hint:'Koefisien suhu untuk tegangan dan untuk arus punya tanda yang berbeda — yang mana yang dampaknya menang terhadap daya?'},
    {type:'pg',q:'Kondisi uji standar (STC) yang dipakai untuk menyatakan daya Wp sebuah modul surya adalah…',opts:['1000 W/m², suhu sel 25 °C, AM 1,5','800 W/m², suhu sel 20 °C, AM 1,0','1200 W/m², suhu sel 40 °C, AM 2,0','500 W/m², suhu udara 25 °C, AM 1,5'],a:0,explain:'STC menetapkan iradiansi 1000 W/m², suhu SEL 25 °C, dan air mass 1,5. Karena di lapangan suhu sel biasanya jauh di atas 25 °C, daya nyata umumnya lebih rendah dari nilai Wp pada label.',hint:'Angka iradiansinya adalah bilangan bulat yang "bersih" dan suhunya suhu ruang — bukan kondisi panas lapangan.'},
    {type:'pg',q:'Satuan Wp (Watt-peak) pada modul surya menyatakan…',opts:['Energi yang dihasilkan modul per hari','Daya keluaran modul pada kondisi uji standar','Daya rata-rata sepanjang tahun','Daya maksimum yang boleh dibebankan ke modul'],a:1,explain:'Wp adalah daya keluaran pada kondisi uji standar, bukan energi maupun rata-rata harian. Energi harian dihitung dari Wp dikali jam matahari ekuivalen dan berbagai faktor rugi, sehingga selalu lebih kecil dari perkalian sederhana.',hint:'Perhatikan satuannya Watt, bukan Watt-jam. Besaran mana yang diukur dengan Watt: daya sesaat atau energi terkumpul?'},
    {type:'pg',q:'Fill factor (FF) sebuah modul surya menggambarkan…',opts:['Persentase luas atap yang tertutup modul','Seberapa "persegi" kurva I-V, yaitu mutu sel','Perbandingan energi siang dan malam','Jumlah sel per modul'],a:1,explain:'FF adalah perbandingan daya di MPP terhadap hasil kali Isc dan Voc. Makin mendekati 1, makin persegi kurva I-V dan makin baik mutu sel. FF rendah menandakan rugi resistansi seri atau kebocoran di dalam sel.',calc:'FF = (Vmpp × Impp) ÷ (Voc × Isc)',hint:'Bandingkan daya nyata di titik terbaik terhadap daya "ideal" andai arus dan tegangan maksimum bisa terjadi bersamaan.'}
  ],

  '3J.02': [
    {type:'pg',q:'Perbedaan mendasar panel monocrystalline dan polycrystalline terletak pada…',opts:['Monocrystalline memakai satu kristal utuh sehingga efisiensinya lebih tinggi','Polycrystalline tidak memakai silikon','Monocrystalline hanya bekerja pada suhu rendah','Polycrystalline tidak butuh inverter'],a:0,explain:'Sel monocrystalline dipotong dari satu kristal silikon tunggal sehingga elektron bergerak lebih leluasa dan efisiensinya lebih tinggi, dengan harga per Wp umumnya lebih mahal. Polycrystalline terbentuk dari banyak butir kristal sehingga ada rugi di batas butir. Keduanya tetap butuh inverter.',hint:'Bedah awalan "mono" dan "poly" — berapa banyak kristal penyusunnya, dan apa akibatnya bagi pergerakan elektron?'},
    {type:'pg',q:'Keunggulan utama panel bifacial dibanding panel konvensional adalah…',opts:['Menyerap cahaya dari sisi depan dan belakang','Tidak memerlukan pembersihan','Bisa bekerja tanpa cahaya matahari','Tegangannya jauh lebih tinggi'],a:0,explain:'Modul bifacial menangkap cahaya langsung di sisi depan dan cahaya pantulan di sisi belakang, sehingga hasil energinya naik bila albedo permukaan di bawahnya tinggi (pasir terang, atap putih). Keunggulan ini hilang bila dipasang rapat ke atap gelap.',hint:'Perhatikan arti "bi" pada namanya, lalu pikirkan syarat apa yang harus dipenuhi permukaan di bawah modul.'},
    {type:'pg',q:'Teknologi PERC pada sel surya bekerja dengan cara…',opts:['Menambah lapisan pasif di sisi belakang sel untuk memantulkan kembali foton','Menghilangkan kebutuhan kaca pelindung','Mengganti silikon dengan tembaga','Menaikkan tegangan sistem menjadi 1500 V'],a:0,explain:'PERC (Passivated Emitter and Rear Cell) menambahkan lapisan pasivasi di sisi belakang sel sehingga foton yang lolos dipantulkan kembali ke lapisan aktif dan rekombinasi elektron ditekan. Hasilnya efisiensi naik beberapa persen tanpa mengubah bahan dasarnya.',hint:'Kepanjangan singkatannya menyebut bagian mana dari sel yang diberi perlakuan tambahan.'},
    {type:'pg',q:'Kelemahan utama panel thin film dibanding panel silikon kristalin adalah…',opts:['Efisiensinya lebih rendah sehingga butuh luas lahan lebih besar','Tidak bisa dipakai di iklim tropis','Tidak menghasilkan arus searah','Umurnya hanya satu tahun'],a:0,explain:'Thin film punya efisiensi per satuan luas yang lebih rendah, sehingga untuk daya yang sama dibutuhkan lahan lebih luas. Kelebihannya justru pada bobot ringan, fleksibilitas, dan kinerja yang relatif lebih baik pada suhu tinggi dan cahaya lemah.',hint:'Kalau efisiensi per meter persegi lebih rendah, sumber daya apa yang harus ditambah untuk mencapai daya yang sama?'},
    {type:'pg',q:'Istilah "degradasi" pada modul surya merujuk pada…',opts:['Penurunan daya keluaran modul seiring bertahun-tahun pemakaian','Kerusakan inverter akibat petir','Penumpukan debu yang bisa dibersihkan','Turunnya tegangan saat malam hari'],a:0,explain:'Degradasi adalah penurunan daya permanen seiring usia, umumnya dijamin produsen sekitar 0,5% per tahun dengan sisa daya sekitar 80% pada tahun ke-25. Penumpukan debu bersifat sementara (soiling) dan bisa dipulihkan dengan pembersihan.',hint:'Bedakan penurunan yang bisa dipulihkan dengan dibersihkan dari penurunan yang tidak bisa dikembalikan lagi.'},
    {type:'pg',q:'Saat memilih panel untuk atap dengan luas terbatas, parameter yang paling menentukan adalah…',opts:['Efisiensi modul (Wp per meter persegi)','Warna bingkai modul','Berat kemasan pengiriman','Panjang kabel bawaan'],a:0,explain:'Pada lahan terbatas, yang menentukan adalah berapa banyak daya yang bisa dipasang per satuan luas, yaitu efisiensi modul. Modul efisiensi tinggi lebih mahal per keping tetapi menghasilkan daya terpasang lebih besar pada atap yang sama.',hint:'Kendalanya adalah LUAS, bukan biaya. Parameter mana yang menghubungkan daya dengan luas?'}
  ],

  '3J.03': [
    {type:'pg',q:'GHI (Global Horizontal Irradiance) adalah…',opts:['Radiasi total yang diterima permukaan horizontal, yaitu komponen langsung ditambah sebaran','Radiasi langsung tegak lurus berkas matahari saja','Radiasi sebaran dari langit saja','Radiasi yang dipantulkan tanah saja'],a:0,explain:'GHI adalah jumlah radiasi langsung pada bidang horizontal (komponen DNI yang diproyeksikan) ditambah radiasi sebaran DHI. DNI adalah radiasi langsung tegak lurus berkas, dan DHI adalah radiasi sebaran dari langit. GHI menjadi acuan utama perhitungan potensi PLTS.',hint:'Uraikan tiga hurufnya: kata "Global" menunjukkan bahwa ini gabungan, bukan salah satu komponen saja.'},
    {type:'pg',q:'Hubungan yang benar antara GHI, DNI, dan DHI pada permukaan horizontal adalah…',opts:['GHI = DNI × cos(sudut zenith) + DHI','GHI = DNI + DHI, tanpa faktor sudut','GHI = DNI − DHI','GHI = DHI × DNI'],a:0,explain:'Radiasi langsung harus diproyeksikan ke bidang horizontal dengan kosinus sudut zenith matahari sebelum dijumlahkan dengan radiasi sebaran. Menjumlahkan langsung tanpa faktor sudut akan melebihkan nilai GHI, terutama saat matahari rendah.',calc:'GHI = DNI × cos(θz) + DHI',hint:'Radiasi langsung datang miring terhadap bidang datar. Faktor trigonometri apa yang dipakai untuk memproyeksikan sebuah vektor ke bidang?'},
    {type:'pg',q:'Istilah "peak sun hours" (jam matahari puncak) menyatakan…',opts:['Jumlah jam ekuivalen dengan iradiansi 1000 W/m² dalam sehari','Jam saat matahari tepat di atas kepala','Lama waktu matahari terlihat di langit','Jumlah jam inverter bekerja'],a:0,explain:'Peak sun hours mengubah total energi radiasi harian (kWh/m²/hari) menjadi jumlah jam ekuivalen pada iradiansi 1000 W/m². Angka ini memudahkan estimasi energi: daya terpasang dikali peak sun hours dikali faktor rugi.',hint:'Angkanya selalu lebih kecil dari lama siang hari. Nilainya adalah energi sehari dibagi oleh nilai iradiansi acuan mana?'},
    {type:'pg',q:'PVGIS dan basis data NASA POWER dipakai dalam perancangan PLTS untuk…',opts:['Memperoleh data radiasi matahari dan iklim jangka panjang di lokasi proyek','Menghitung pajak proyek','Mendaftarkan izin usaha listrik','Mengukur tahanan pentanahan'],a:0,explain:'Keduanya menyediakan data radiasi dan iklim historis berbasis satelit yang menjadi masukan perhitungan energi tahunan. Data ini dipakai saat pengukuran di lokasi belum tersedia, dengan catatan ada ketidakpastian yang harus diperhitungkan.',hint:'Pikirkan data apa yang paling dibutuhkan sebelum ada alat ukur terpasang di lokasi proyek.'},
    {type:'pg',q:'Wilayah Indonesia umumnya memiliki nilai GHI harian rata-rata di kisaran…',opts:['Sekitar 4–5,5 kWh/m² per hari','Sekitar 0,5–1 kWh/m² per hari','Sekitar 15–20 kWh/m² per hari','Sekitar 40 kWh/m² per hari'],a:0,explain:'Sebagai wilayah tropis ekuatorial, Indonesia menerima radiasi harian rata-rata sekitar 4–5,5 kWh/m² per hari dengan variasi antar-daerah. Nilai belasan atau puluhan kWh/m² per hari tidak mungkin dicapai di permukaan bumi.',hint:'Kalikan iradiansi puncak 1000 W/m² dengan beberapa jam efektif — hasilnya memberi batas atas yang masuk akal.'},
    {type:'pg',q:'Mengapa data radiasi satelit tetap perlu diverifikasi untuk proyek PLTS skala besar?',opts:['Karena ada ketidakpastian dan kondisi lokal seperti kabut atau debu yang tidak tertangkap','Karena data satelit selalu salah total','Karena satelit hanya mengukur pada malam hari','Karena data satelit tidak boleh dipakai secara hukum'],a:0,explain:'Data satelit punya ketidakpastian beberapa persen dan tidak menangkap kondisi mikro seperti kabut lokal, asap, atau debu industri. Pada proyek besar, selisih beberapa persen berdampak besar pada perhitungan pendapatan, sehingga sering dilakukan pengukuran di lokasi.',hint:'Pikirkan dampak selisih beberapa persen energi tahunan terhadap perhitungan keuangan proyek puluhan miliar rupiah.'}
  ],

  '3J.04': [
    {type:'pg',q:'Untuk lokasi di belahan bumi selatan seperti sebagian besar Indonesia, orientasi modul surya yang optimal umumnya menghadap…',opts:['Utara','Selatan','Timur','Barat'],a:0,explain:'Di belahan bumi selatan, lintasan matahari rata-rata berada di sisi utara langit, sehingga modul dihadapkan ke utara. Kebalikannya berlaku di belahan bumi utara. Untuk lokasi sangat dekat khatulistiwa, pengaruh orientasi mengecil dan kemiringan lebih ditentukan kebutuhan pembersihan diri oleh air hujan.',hint:'Tentukan dulu di sisi langit mana matahari rata-rata berada bila kamu berdiri di selatan khatulistiwa.'},
    {type:'pg',q:'Dampak bayangan (shading) yang mengenai sebagian kecil satu modul dalam rangkaian seri adalah…',opts:['Menurunkan keluaran seluruh rangkaian seri, bukan hanya modul itu','Hanya menurunkan keluaran modul yang tertutup','Tidak berdampak karena ada dioda','Menaikkan tegangan rangkaian'],a:0,explain:'Dalam rangkaian seri, arus yang mengalir dibatasi oleh modul terlemah, sehingga bayangan sebagian pada satu modul menurunkan arus seluruh string. Dioda bypass mengurangi kerugian dan mencegah titik panas, tetapi tidak menghilangkan penurunan energi.',hint:'Pada rangkaian seri, besaran apa yang harus sama di semua komponen, dan komponen mana yang menentukan batasnya?'},
    {type:'pg',q:'Fungsi utama analisis shading saat site survey adalah…',opts:['Menentukan jarak antar-baris dan posisi modul agar bayangan tidak menutupi modul pada jam produktif','Menentukan warna modul','Menghitung pajak bangunan','Memilih merek inverter'],a:0,explain:'Analisis bayangan menentukan jarak antar-baris (row pitch) dan penempatan modul agar bayangan pohon, parapet, atau baris di depannya tidak menutupi modul pada jam produksi utama. Jarak yang terlalu rapat menaikkan kapasitas terpasang tetapi menurunkan hasil energi.',hint:'Hasil analisis ini berupa angka jarak dan posisi — untuk menghindari apa, pada rentang jam berapa?'},
    {type:'pg',q:'Istilah "row pitch" pada PLTS ground-mount adalah…',opts:['Jarak antar-baris larik modul','Kemiringan modul terhadap horizontal','Tinggi tiang penyangga','Panjang kabel DC antar-modul'],a:0,explain:'Row pitch adalah jarak antar-baris larik modul, ditentukan agar baris depan tidak membayangi baris belakang pada jam kritis. Kemiringan disebut tilt, dan sudut hadap disebut azimuth.',hint:'Kata "row" menunjuk pada baris. Besaran antar-baris yang mana yang perlu diatur agar tidak saling membayangi?'},
    {type:'pg',q:'Pada atap datar di daerah tropis, kemiringan modul minimal sekitar 10° tetap dianjurkan terutama agar…',opts:['Air hujan bisa membilas debu sehingga modul tidak cepat kotor','Modul bisa menghasilkan tegangan lebih tinggi','Modul tidak memerlukan pembumian','Inverter bisa dipasang di bawah modul'],a:0,explain:'Modul yang dipasang benar-benar datar membuat air dan debu mengendap, sehingga rugi soiling naik cepat. Kemiringan minimal sekitar 10° membantu air hujan membilas permukaan. Pengaruhnya pada tegangan tidak signifikan, dan pembumian tetap wajib.',hint:'Pikirkan apa yang terjadi pada air dan debu di permukaan yang benar-benar rata setelah hujan.'},
    {type:'pg',q:'Dalam site survey PLTS rooftop, pemeriksaan kekuatan struktur atap penting karena…',opts:['Atap harus mampu menahan beban modul, rangka, dan beban angin','Modul memerlukan pendingin air dari atap','Struktur atap menentukan tegangan sistem','Atap harus menghantarkan arus ke tanah'],a:0,explain:'Modul dan rangkanya menambah beban mati, sementara angin menimbulkan beban hisap yang bisa jauh lebih besar. Tanpa pemeriksaan struktur, pemasangan berisiko merusak atap atau terlepas saat angin kencang.',hint:'Selain berat modul itu sendiri, gaya alam apa yang justru bisa mengangkat rangkaian modul di atas atap?'}
  ],

  '3J.05': [
    {type:'pg',q:'Fungsi utama inverter pada sistem PLTS adalah…',opts:['Mengubah arus searah dari modul menjadi arus bolak-balik yang sesuai jaringan','Menyimpan energi listrik','Menaikkan tegangan DC modul','Membersihkan modul secara otomatis'],a:0,explain:'Modul surya menghasilkan arus searah, sedangkan jaringan dan sebagian besar beban memakai arus bolak-balik. Inverter melakukan konversi itu sekaligus menjalankan MPPT dan fungsi proteksi jaringan. Penyimpanan energi adalah tugas baterai.',hint:'Bandingkan bentuk listrik yang KELUAR dari modul dengan bentuk listrik yang DIBUTUHKAN jaringan.'},
    {type:'pg',q:'Keunggulan microinverter dibanding string inverter terutama terasa pada kondisi…',opts:['Atap dengan orientasi beragam atau bayangan parsial','Lahan datar luas tanpa halangan','Sistem dengan tegangan DC sangat tinggi','Sistem tanpa sambungan jaringan'],a:0,explain:'Microinverter melakukan MPPT per modul, sehingga modul yang terbayangi tidak menarik turun kinerja modul lain. Keunggulan ini paling terasa pada atap dengan banyak arah hadap atau bayangan. Pada lahan luas seragam, string atau central inverter lebih ekonomis.',hint:'Kelebihannya adalah pelacakan daya per modul. Kondisi lapangan seperti apa yang membuat tiap modul berbeda-beda keluarannya?'},
    {type:'pg',q:'Fungsi MPPT pada inverter PLTS adalah…',opts:['Menjaga titik kerja larik tetap pada daya maksimum saat radiasi dan suhu berubah','Membatasi arus keluaran agar tidak melebihi 10 A','Mengubah tegangan jaringan menjadi 20 kV','Menghitung tagihan listrik'],a:0,explain:'MPPT (Maximum Power Point Tracking) terus menyesuaikan titik kerja tegangan-arus larik agar berada di MPP, yang posisinya bergeser mengikuti perubahan radiasi dan suhu. Tanpa MPPT, sebagian besar potensi daya terbuang.',hint:'Posisi titik daya maksimum tidak tetap sepanjang hari. Apa yang harus dilakukan alat ini terhadap titik kerja itu?'},
    {type:'pg',q:'Istilah DC/AC ratio (oversizing) pada desain PLTS berarti…',opts:['Perbandingan daya puncak larik DC terhadap daya nominal inverter AC','Perbandingan jumlah kabel DC dan AC','Perbandingan tegangan DC dan AC','Perbandingan biaya DC dan AC'],a:0,explain:'DC/AC ratio membandingkan kapasitas terpasang modul terhadap kapasitas inverter, umumnya 1,1–1,3. Karena modul jarang mencapai daya puncak, sedikit kelebihan kapasitas DC membuat inverter bekerja lebih sering mendekati beban optimal, dengan konsekuensi pemangkasan (clipping) saat puncak.',hint:'Bandingkan dua angka kapasitas: sisi modul dan sisi inverter. Mengapa sisi modul boleh dibuat lebih besar?'},
    {type:'pg',q:'Central inverter umumnya dipilih untuk proyek…',opts:['PLTS skala besar dengan lahan seragam','PLTS rumah tinggal 3 kWp','Sistem portabel untuk berkemah','Penerangan jalan tenaga surya'],a:0,explain:'Central inverter berkapasitas ratusan kW sampai megawatt dan paling ekonomis pada pembangkit skala besar dengan kondisi larik seragam. Untuk sistem kecil dan atap rumah, string inverter atau microinverter jauh lebih sesuai.',hint:'Perhatikan rentang kapasitas alatnya, lalu cocokkan dengan ukuran proyek yang sepadan.'},
    {type:'pg',q:'Efisiensi inverter modern umumnya berada di kisaran…',opts:['96–99%','60–70%','40–50%','100% tanpa rugi'],a:0,explain:'Inverter PLTS modern mencapai efisiensi puncak 96–99%. Nilai 100% tidak mungkin karena selalu ada rugi penyaklaran dan panas. Efisiensi yang sering dipakai dalam perhitungan energi adalah efisiensi tertimbang seperti Euro atau CEC efficiency.',hint:'Ingat bahwa setiap alat elektronika daya pasti menimbulkan panas, jadi ada batas atas yang tidak pernah tercapai.'}
  ],

  '4J.01': [
    {type:'pg',q:'Performance Ratio (PR) sebuah PLTS menyatakan…',opts:['Perbandingan energi nyata yang dihasilkan terhadap energi ideal secara teoretis','Perbandingan biaya terhadap daya terpasang','Perbandingan jumlah modul dan inverter','Perbandingan daya siang dan malam'],a:0,explain:'PR membandingkan energi yang benar-benar dihasilkan terhadap energi yang secara teori bisa dihasilkan pada radiasi yang sama, sehingga menangkap seluruh rugi: suhu, kabel, kotoran, ketidakcocokan, dan ketersediaan inverter. PLTS yang sehat umumnya berada di kisaran 75–85%.',hint:'Angka ini menilai MUTU sistem, bukan besarnya. Ia membandingkan hasil nyata dengan hasil ideal pada radiasi yang sama.'},
    {type:'pg',q:'Untuk PLTS 200 kWp dengan peak sun hours 4,5 jam/hari dan performance ratio 0,8, perkiraan energi harian adalah…',opts:['720 kWh','900 kWh','200 kWh','1800 kWh'],a:0,explain:'Energi harian diperkirakan dengan mengalikan daya terpasang, peak sun hours, dan performance ratio: 200 × 4,5 × 0,8 = 720 kWh. Melupakan performance ratio akan melebihkan estimasi menjadi 900 kWh.',calc:'E = P_terpasang × Peak Sun Hours × PR',hint:'Kalikan ketiga angka yang diberikan; jangan berhenti setelah dua angka pertama.'},
    {type:'pg',q:'Jumlah modul maksimum dalam satu string dibatasi terutama oleh…',opts:['Tegangan rangkaian terbuka total pada suhu terdingin tidak boleh melewati batas tegangan inverter','Panjang kabel yang tersedia','Jumlah baut rangka','Warna modul'],a:0,explain:'Voc naik saat suhu turun, sehingga perhitungan memakai suhu terendah yang mungkin terjadi di lokasi. Bila hasilnya melewati tegangan masukan maksimum inverter (umumnya 1000 atau 1500 V), inverter bisa rusak. Batas bawah jumlah modul ditentukan tegangan minimum MPPT pada suhu tertinggi.',hint:'Voc berubah terhadap suhu. Kondisi suhu ekstrem yang mana yang menghasilkan tegangan string paling tinggi?'},
    {type:'pg',q:'Rugi mismatch pada larik PLTS terjadi karena…',opts:['Modul dalam satu string tidak persis sama karakteristiknya sehingga dibatasi yang terlemah','Kabel AC terlalu panjang','Inverter tidak punya MPPT','Modul dipasang terlalu tinggi'],a:0,explain:'Selisih kecil karakteristik antar-modul membuat arus string dibatasi modul terlemah. Karena itu modul dikelompokkan berdasarkan toleransi daya (binning) dan dipasang dalam string dengan karakteristik sedekat mungkin.',hint:'Pada rangkaian seri, satu komponen yang paling lemah menentukan apa bagi seluruh rangkaian?'},
    {type:'pg',q:'Untuk PLTS yang terhubung jaringan, fungsi anti-islanding pada inverter bertujuan…',opts:['Menghentikan suplai saat jaringan padam agar tidak membahayakan petugas','Menaikkan tegangan saat jaringan lemah','Menyimpan energi ke baterai','Menurunkan harmonisa'],a:0,explain:'Bila jaringan padam sementara inverter tetap menyuplai, bagian jaringan tersebut tetap bertegangan dan membahayakan petugas yang memperbaiki. Fungsi anti-islanding mendeteksi hilangnya jaringan dan memutus suplai dalam waktu singkat sesuai grid code.',hint:'Pikirkan keselamatan orang yang sedang memperbaiki jaringan yang dikira sudah mati.'},
    {type:'pg',q:'Dokumen yang menjadi dasar teknis sambungan PLTS ke jaringan distribusi PLN adalah…',opts:['Aturan jaringan/grid code dan persyaratan teknis interkoneksi','Akta pendirian perusahaan','Sertifikat tanah lokasi','Polis asuransi kebakaran'],a:0,explain:'Grid code dan persyaratan teknis interkoneksi mengatur batas tegangan, frekuensi, harmonisa, faktor daya, dan perilaku inverter saat gangguan. Dokumen legal lain diperlukan secara administratif, tetapi bukan acuan teknis sambungan.',hint:'Cari dokumen yang isinya berupa batasan teknis kelistrikan, bukan dokumen legalitas perusahaan.'}
  ],

  '5J.06': [
    {type:'pg',q:'Levelized Cost of Energy (LCOE) sebuah proyek PLTS menyatakan…',opts:['Biaya rata-rata per kWh sepanjang umur proyek setelah memperhitungkan investasi dan operasi','Harga jual listrik yang ditetapkan pemerintah','Biaya pemasangan per modul','Pajak yang dibayar per tahun'],a:0,explain:'LCOE membagi nilai kini seluruh biaya (investasi, operasi, pemeliharaan, penggantian) dengan nilai kini seluruh energi yang dihasilkan sepanjang umur proyek. Angka ini memudahkan perbandingan antar-teknologi pembangkit pada satuan yang sama.',hint:'Satuannya adalah rupiah per kWh sepanjang umur proyek — berarti ada dua hal yang dibagi: total biaya dan total apa?'},
    {type:'pg',q:'Dalam evaluasi kelayakan proyek, NPV positif berarti…',opts:['Nilai kini arus kas masuk melebihi nilai kini arus kas keluar','Proyek pasti selesai tepat waktu','Proyek tidak memerlukan pinjaman','Pendapatan tahunan selalu naik'],a:0,explain:'NPV (Net Present Value) menjumlahkan seluruh arus kas yang didiskonto ke nilai sekarang. NPV positif berarti proyek menghasilkan nilai lebih besar dari biaya modalnya pada tingkat diskonto yang dipakai, sehingga layak secara finansial.',hint:'Kata "Net" berarti selisih. Dua kelompok arus kas mana yang diperbandingkan, dan dalam nilai kapan?'},
    {type:'pg',q:'DSCR (Debt Service Coverage Ratio) dipakai pemberi pinjaman untuk menilai…',opts:['Kemampuan arus kas proyek menutup kewajiban pokok dan bunga','Jumlah modul yang terpasang','Efisiensi inverter','Tingkat radiasi lokasi'],a:0,explain:'DSCR membandingkan arus kas operasi bersih terhadap kewajiban pembayaran pokok dan bunga pada periode yang sama. Nilai di bawah 1 berarti arus kas tidak cukup membayar utang, sehingga pemberi pinjaman biasanya mensyaratkan nilai minimum di atas 1,2.',calc:'DSCR = Arus kas operasi bersih ÷ (Pokok + Bunga)',hint:'Kata "coverage" menunjuk pada kemampuan menutup sesuatu. Kewajiban apa yang harus tertutup oleh arus kas?'},
    {type:'pg',q:'IRR sebuah proyek adalah tingkat diskonto yang membuat…',opts:['NPV proyek sama dengan nol','Biaya investasi menjadi nol','Pendapatan tahunan maksimum','Umur proyek terpendek'],a:0,explain:'IRR (Internal Rate of Return) adalah tingkat diskonto yang membuat NPV bernilai nol. Proyek umumnya dinilai layak bila IRR melebihi biaya modal yang disyaratkan pemilik proyek.',hint:'Hubungkan IRR dengan NPV: pada nilai NPV berapa keduanya bertemu?'},
    {type:'pg',q:'Risiko terbesar yang memengaruhi pendapatan proyek PLTS jangka panjang adalah…',opts:['Ketidakpastian hasil energi dan keandalan pembeli listrik membayar','Warna modul memudar','Merek baut rangka','Bahasa manual inverter'],a:0,explain:'Pendapatan proyek bergantung pada berapa banyak energi yang benar-benar dihasilkan dan apakah pembeli listrik membayar sesuai perjanjian. Karena itu analisis P50/P90 dan penilaian kelayakan kredit pembeli menjadi bagian wajib uji tuntas proyek.',hint:'Pendapatan = energi terjual × harga yang benar-benar dibayar. Ketidakpastian ada di kedua faktor itu.'},
    {type:'pg',q:'Istilah P90 dalam energy yield assessment berarti…',opts:['Tingkat produksi energi yang peluang tercapainya 90%','Produksi 90% dari kapasitas terpasang','Efisiensi sistem 90%','Umur proyek 90 tahun'],a:0,explain:'P90 adalah nilai produksi energi yang secara statistik punya peluang 90% untuk tercapai atau terlampaui, sehingga lebih konservatif daripada P50 yang peluangnya 50%. Pemberi pinjaman biasanya memakai P90 sebagai dasar perhitungan kemampuan bayar.',hint:'Angka 90 di sini adalah PELUANG, bukan persentase kapasitas maupun efisiensi.'}
  ],

  '6J.04': [
    {type:'pg',q:'Energy Yield Assessment (EYA) sebuah proyek PLTS bertujuan…',opts:['Memperkirakan produksi energi tahunan beserta ketidakpastiannya','Menentukan warna dan merek modul','Menghitung pajak bumi dan bangunan','Merancang jalur evakuasi kebakaran'],a:0,explain:'EYA menghitung perkiraan energi tahunan dari data radiasi, rancangan sistem, dan seluruh rugi, sekaligus menyatakan ketidakpastiannya dalam bentuk P50, P75, dan P90. Hasilnya menjadi dasar model keuangan dan keputusan pendanaan.',hint:'Hasil akhirnya berupa angka energi per tahun — disertai apa, sehingga pemberi pinjaman bisa menilai risikonya?'},
    {type:'pg',q:'Perbedaan P50 dan P90 dalam laporan EYA adalah…',opts:['P50 adalah nilai tengah harapan produksi, P90 adalah nilai konservatif dengan peluang tercapai lebih tinggi','P50 untuk musim kemarau, P90 untuk musim hujan','P50 mengukur daya, P90 mengukur tegangan','Keduanya sama, hanya berbeda satuan'],a:0,explain:'P50 adalah perkiraan produksi dengan peluang tercapai 50%, sedangkan P90 lebih rendah nilainya karena peluang tercapainya 90%. Selisih keduanya mencerminkan besarnya ketidakpastian: makin besar ketidakpastian, makin jauh P90 di bawah P50.',hint:'Makin tinggi peluang yang diminta agar target tercapai, ke arah mana nilai targetnya harus digeser?'},
    {type:'pg',q:'Rugi yang harus diperhitungkan dalam EYA mencakup, kecuali…',opts:['Rugi akibat suhu, soiling, mismatch, kabel, dan ketersediaan inverter','Biaya sewa kantor pusat perusahaan','Rugi akibat bayangan','Rugi konversi pada inverter'],a:1,explain:'EYA menghitung rugi teknis yang mengurangi energi: suhu, kotoran, ketidakcocokan modul, tahanan kabel, bayangan, konversi inverter, dan ketersediaan peralatan. Biaya sewa kantor adalah biaya operasional perusahaan yang masuk model keuangan, bukan rugi energi.',hint:'Semua pilihan kecuali satu adalah hal yang mengurangi kWh. Cari yang mengurangi RUPIAH, bukan energi.'},
    {type:'pg',q:'Degradasi modul dalam perhitungan produksi jangka panjang biasanya diasumsikan sekitar…',opts:['0,4–0,7% per tahun','5% per tahun','15% per tahun','Nol, karena modul tidak menurun'],a:0,explain:'Produsen umumnya menjamin degradasi linier sekitar 0,4–0,7% per tahun sehingga daya tersisa sekitar 80–85% pada tahun ke-25. Asumsi degradasi yang terlalu optimistis membuat proyeksi pendapatan jangka panjang tidak realistis.',hint:'Kalau garansi menjanjikan sekitar 80% daya tersisa setelah 25 tahun, berapa penurunan rata-rata tiap tahunnya?'},
    {type:'pg',q:'Availability dalam konteks kinerja PLTS menyatakan…',opts:['Persentase waktu sistem siap beroperasi tanpa gangguan atau pemeliharaan','Jumlah modul yang tersedia di gudang','Ketersediaan lahan untuk perluasan','Jumlah teknisi yang bertugas'],a:0,explain:'Availability mengukur porsi waktu peralatan siap beroperasi, biasanya disyaratkan di atas 98% dalam kontrak operasi dan pemeliharaan. Availability rendah langsung menurunkan energi terjual meski radiasi mataharinya bagus.',hint:'Istilah ini berbicara tentang WAKTU sistem siap bekerja, bukan tentang jumlah barang.'},
    {type:'pg',q:'Independent engineer dalam pembiayaan proyek PLTS berperan…',opts:['Menelaah asumsi teknis proyek secara independen untuk kepentingan pemberi pinjaman','Memasang modul di lapangan','Menjual listrik ke pelanggan','Menerbitkan izin usaha'],a:0,explain:'Independent engineer menelaah rancangan, asumsi produksi, mutu peralatan, dan rencana operasi secara independen agar pemberi pinjaman memperoleh penilaian risiko yang tidak bias dari pengembang. Perannya menelaah, bukan melaksanakan pekerjaan konstruksi.',hint:'Kata kuncinya "independent" — pihak ini bekerja untuk siapa, dan pekerjaannya menelaah atau membangun?'}
  ],

  // ===================================================================
  // S11 · Carbon & Sustainability Academy (kode 3K / 4K / 5K / 6K)
  // ===================================================================

  '3K.01': [
    {type:'pg',q:'Efek rumah kaca terjadi karena gas tertentu di atmosfer…',opts:['Menyerap dan memancarkan kembali radiasi inframerah dari permukaan bumi','Memantulkan seluruh sinar matahari kembali ke angkasa','Menghalangi cahaya tampak mencapai permukaan','Menambah kandungan oksigen atmosfer'],a:0,explain:'Gas rumah kaca meneruskan radiasi gelombang pendek dari matahari, tetapi menyerap radiasi inframerah gelombang panjang yang dipancarkan bumi lalu memancarkannya kembali ke segala arah, termasuk ke bawah. Itulah yang menahan panas di dekat permukaan.',hint:'Bandingkan panjang gelombang sinar yang MASUK dari matahari dengan yang DIPANCARKAN kembali oleh permukaan bumi.'},
    {type:'pg',q:'Kesepakatan Paris menargetkan pembatasan kenaikan suhu rata-rata global pada…',opts:['Jauh di bawah 2 °C dengan upaya membatasi pada 1,5 °C','Tepat 5 °C','Di bawah 10 °C','Tidak menetapkan angka apa pun'],a:0,explain:'Paris Agreement menetapkan target menahan kenaikan suhu rata-rata global jauh di bawah 2 °C dibanding tingkat pra-industri, dengan upaya membatasinya pada 1,5 °C. Angka 1,5 °C inilah yang menjadi acuan banyak target net zero.',hint:'Dua angka yang sering disebut bersamaan dalam pemberitaan iklim, keduanya di bawah 2.'},
    {type:'pg',q:'Istilah "net zero emission" berarti…',opts:['Emisi yang dilepas diimbangi oleh penyerapan sehingga jumlah bersihnya nol','Tidak ada emisi sama sekali yang boleh dilepas','Emisi dipindahkan ke negara lain','Emisi diukur hanya sekali setahun'],a:0,explain:'Net zero berarti emisi yang masih dilepas diimbangi dengan penyerapan atau penghilangan karbon dalam jumlah setara, sehingga neraca bersihnya nol. Kondisi tanpa emisi sama sekali disebut zero emission atau absolute zero.',hint:'Perhatikan kata "net" — ini soal NERACA antara yang dilepas dan yang diserap, bukan larangan total.'},
    {type:'pg',q:'Sektor penyumbang emisi gas rumah kaca terbesar secara global berasal dari…',opts:['Produksi dan penggunaan energi, termasuk listrik, transportasi, dan industri','Peternakan ikan hias','Pariwisata laut','Industri percetakan'],a:0,explain:'Sistem energi — pembangkitan listrik, transportasi, pemanasan, dan proses industri — menyumbang bagian terbesar emisi global. Karena itu transisi energi menjadi tuas utama penurunan emisi, dan sektor kelistrikan berada di pusatnya.',hint:'Pikirkan aktivitas yang paling banyak membakar bahan bakar fosil setiap hari di seluruh dunia.'},
    {type:'pg',q:'Perbedaan mitigasi dan adaptasi dalam kebijakan iklim adalah…',opts:['Mitigasi menurunkan emisi, adaptasi menyesuaikan diri terhadap dampak yang sudah terjadi','Mitigasi untuk negara maju, adaptasi untuk negara berkembang','Mitigasi bersifat wajib, adaptasi bersifat sukarela','Keduanya istilah yang sama persis'],a:0,explain:'Mitigasi berupaya menekan sumber emisi atau menambah penyerapan agar perubahan iklim tidak makin parah, sedangkan adaptasi menyiapkan masyarakat dan infrastruktur menghadapi dampak yang sudah tidak terhindarkan seperti banjir rob dan kekeringan.',hint:'Satu bekerja pada PENYEBAB, satu lagi pada AKIBAT yang sudah telanjur terjadi.'},
    {type:'pg',q:'Indonesia menyampaikan target penurunan emisinya kepada dunia melalui dokumen…',opts:['NDC (Nationally Determined Contribution)','SLO (Sertifikat Laik Operasi)','RUPTL','AMDAL'],a:0,explain:'NDC adalah dokumen komitmen penurunan emisi tiap negara di bawah Paris Agreement, yang diperbarui secara berkala. RUPTL adalah rencana penyediaan tenaga listrik, AMDAL adalah kajian dampak lingkungan proyek, dan SLO adalah sertifikat kelaikan instalasi.',hint:'Cari dokumen yang disampaikan ke forum internasional, bukan dokumen perencanaan atau perizinan dalam negeri.'}
  ],

  '3K.02': [
    {type:'pg',q:'Global Warming Potential (GWP) sebuah gas rumah kaca menyatakan…',opts:['Kemampuan gas menahan panas relatif terhadap CO₂ pada rentang waktu tertentu','Jumlah gas yang ada di atmosfer','Harga gas tersebut di pasar','Kecepatan gas menyebar di udara'],a:0,explain:'GWP membandingkan efek pemanasan sejumlah massa gas tertentu terhadap massa CO₂ yang sama, biasanya pada horizon 100 tahun. Dengan GWP, berbagai gas bisa dijumlahkan dalam satuan setara CO₂ (CO₂e).',hint:'Angka ini selalu relatif terhadap satu gas acuan. Gas mana yang dijadikan patokan dengan nilai 1?'},
    {type:'pg',q:'Di antara gas berikut, yang memiliki GWP paling tinggi adalah…',opts:['SF₆ (sulfur heksafluorida)','CO₂','CH₄ (metana)','Uap air biasa'],a:0,explain:'SF₆ yang dipakai sebagai media isolasi pada switchgear tegangan tinggi memiliki GWP sekitar puluhan ribu kali CO₂ dan bertahan sangat lama di atmosfer. Karena itu kebocoran SF₆ pada peralatan listrik menjadi perhatian khusus industri ketenagalistrikan.',hint:'Satu di antaranya justru banyak dipakai di peralatan listrik tegangan tinggi — dan itulah yang paling berbahaya bagi iklim.'},
    {type:'pg',q:'Satuan CO₂e (setara CO₂) dipakai agar…',opts:['Berbagai jenis gas rumah kaca bisa dijumlahkan dalam satu satuan yang sebanding','Emisi terlihat lebih kecil dalam laporan','Perusahaan tidak perlu mengukur metana','Data emisi bisa dirahasiakan'],a:0,explain:'Tiap gas punya daya pemanasan berbeda, sehingga tidak bisa dijumlahkan begitu saja berdasarkan massa. Dengan mengalikan massa tiap gas dengan GWP-nya, semuanya dikonversi ke satuan setara CO₂ dan bisa dijumlahkan menjadi total emisi.',hint:'Masalahnya adalah menjumlahkan besaran yang tidak setara. Konversi ke satuan bersama menyelesaikan masalah apa?'},
    {type:'pg',q:'Metana (CH₄) menjadi perhatian khusus karena…',opts:['GWP-nya jauh di atas CO₂ meski umurnya di atmosfer lebih pendek','Tidak bisa diukur dengan alat apa pun','Tidak dihasilkan aktivitas manusia','Justru mendinginkan atmosfer'],a:0,explain:'Metana punya GWP sekitar 28–30 kali CO₂ pada horizon 100 tahun, dengan umur atmosfer sekitar satu dekade. Karena dampaknya kuat dan umurnya pendek, menekan kebocoran metana memberi hasil pendinginan yang relatif cepat.',hint:'Ada dua sifat yang berlawanan di sini: dampaknya kuat, tetapi ia tidak bertahan lama di atmosfer.'},
    {type:'pg',q:'Emisi SF₆ di sektor ketenagalistrikan paling mungkin berasal dari…',opts:['Kebocoran pada GIS dan pemutus tenaga tegangan tinggi','Pembakaran batubara di boiler','Penggunaan kabel tembaga','Pemakaian lampu LED'],a:0,explain:'SF₆ dipakai sebagai media isolasi dan pemadam busur api pada Gas Insulated Switchgear serta pemutus tenaga tegangan tinggi. Emisinya muncul dari kebocoran, pengisian ulang, dan penanganan saat pemeliharaan atau pembongkaran peralatan.',hint:'Cari peralatan listrik yang memang sengaja diisi gas khusus sebagai bahan isolasinya.'},
    {type:'pg',q:'Pernyataan yang benar tentang CO₂ dibanding gas rumah kaca lain adalah…',opts:['GWP-nya paling rendah tetapi jumlahnya paling besar sehingga dampaknya dominan','GWP-nya tertinggi sehingga paling berbahaya per kilogram','Jumlahnya paling sedikit di atmosfer','Tidak berasal dari pembakaran bahan bakar'],a:0,explain:'CO₂ dipakai sebagai acuan dengan GWP 1, jadi paling rendah per satuan massa. Namun volumenya jauh terbesar karena berasal dari pembakaran bahan bakar fosil di seluruh dunia, sehingga kontribusinya terhadap pemanasan paling dominan.',hint:'Dampak total = dampak per kilogram × jumlah kilogram. Untuk CO₂, faktor mana yang besar dan mana yang kecil?'}
  ],

  '3K.03': [
    {type:'pg',q:'Menurut GHG Protocol, emisi Scope 1 adalah…',opts:['Emisi langsung dari sumber yang dimiliki atau dikendalikan perusahaan','Emisi dari listrik yang dibeli','Emisi dari rantai pasok pemasok','Emisi dari penggunaan produk oleh konsumen'],a:0,explain:'Scope 1 mencakup emisi langsung dari sumber milik atau kendali perusahaan, misalnya pembakaran bahan bakar di boiler, genset, dan kendaraan operasional. Listrik yang dibeli masuk Scope 2, sedangkan rantai pasok dan penggunaan produk masuk Scope 3.',hint:'Kata kuncinya "langsung" — cerobong atau knalpot itu milik siapa?'},
    {type:'pg',q:'Emisi dari listrik yang dibeli perusahaan dari PLN dikategorikan sebagai…',opts:['Scope 2','Scope 1','Scope 3','Tidak dihitung'],a:0,explain:'Scope 2 mencakup emisi tidak langsung dari energi yang dibeli: listrik, uap, panas, atau pendingin. Emisinya terjadi di pembangkit milik pihak lain, tetapi dihitung oleh pemakai karena permintaannyalah yang memicu pembangkitan itu.',hint:'Emisinya terjadi di luar pagar pabrik, tetapi dipicu oleh energi yang dibeli — kategori ini berdiri sendiri di antara langsung dan rantai nilai.'},
    {type:'pg',q:'Yang termasuk emisi Scope 3 adalah…',opts:['Emisi dari perjalanan dinas, rantai pasok, dan penggunaan produk oleh pelanggan','Emisi dari genset milik perusahaan','Emisi dari listrik yang dibeli','Emisi dari kendaraan operasional perusahaan'],a:0,explain:'Scope 3 mencakup seluruh emisi tidak langsung lain di sepanjang rantai nilai, dari hulu (pembelian barang dan jasa, perjalanan dinas) sampai hilir (distribusi dan penggunaan produk). Scope 3 biasanya terbesar sekaligus paling sulit diukur.',hint:'Sisihkan dulu emisi dari alat milik sendiri dan dari energi yang dibeli; sisanya sepanjang rantai nilai masuk kategori ini.'},
    {type:'pg',q:'Emission factor dalam perhitungan jejak karbon dipakai untuk…',opts:['Mengubah data aktivitas seperti kWh atau liter bahan bakar menjadi jumlah emisi','Menentukan harga karbon di bursa','Menghitung pajak penghasilan','Mengukur suhu udara'],a:0,explain:'Emission factor menyatakan jumlah emisi per satuan aktivitas, misalnya kg CO₂e per kWh listrik atau per liter solar. Emisi dihitung dengan mengalikan data aktivitas dengan faktor emisinya, sehingga mutu data aktivitas sangat menentukan.',calc:'Emisi = Data aktivitas × Emission factor',hint:'Kamu punya data pemakaian dalam kWh, tapi butuh hasil dalam kg CO₂e. Apa yang menjembatani dua satuan itu?'},
    {type:'pg',q:'Sebuah pabrik memakai 500.000 kWh listrik setahun dengan faktor emisi jaringan 0,8 kg CO₂e/kWh. Emisi Scope 2-nya adalah…',opts:['400 ton CO₂e','40 ton CO₂e','4.000 ton CO₂e','625 ton CO₂e'],a:0,explain:'Emisi dihitung 500.000 kWh × 0,8 kg CO₂e/kWh = 400.000 kg CO₂e, yang setara 400 ton CO₂e. Kesalahan yang sering terjadi adalah lupa mengubah kilogram menjadi ton.',calc:'Emisi = kWh × faktor emisi, lalu kg ÷ 1.000 = ton',hint:'Kalikan dulu, lalu perhatikan baik-baik perubahan satuan dari kilogram ke ton.'},
    {type:'pg',q:'Tahun dasar (base year) dalam inventarisasi emisi perusahaan berguna untuk…',opts:['Menjadi titik acuan pembanding kemajuan penurunan emisi','Menentukan usia perusahaan','Menghitung penyusutan aset','Menetapkan tahun pajak'],a:0,explain:'Tahun dasar adalah tahun acuan yang dipakai untuk mengukur kemajuan penurunan emisi. Tanpa tahun dasar yang konsisten dan terdokumentasi, klaim penurunan emisi tidak bisa diverifikasi karena tidak jelas dibandingkan dengan apa.',hint:'Klaim "turun 30%" tidak berarti apa-apa tanpa menyebut turun dibanding apa.'}
  ],

  '4K.01': [
    {type:'pg',q:'Perbedaan pasar karbon sukarela (VCM) dan pasar kepatuhan (compliance) adalah…',opts:['VCM didorong komitmen mandiri, pasar kepatuhan didorong kewajiban regulasi','VCM hanya untuk negara maju','Pasar kepatuhan tidak melibatkan uang','Keduanya diatur satu lembaga yang sama'],a:0,explain:'Pasar kepatuhan lahir dari kewajiban regulasi seperti batas emisi yang ditetapkan pemerintah, sedangkan pasar sukarela digerakkan komitmen perusahaan sendiri untuk mengimbangi emisinya. Keduanya punya standar, harga, dan tingkat pengawasan yang berbeda.',hint:'Tanyakan apa yang memaksa pembeli membeli: aturan pemerintah, atau keputusan sendiri?'},
    {type:'pg',q:'Satu unit kredit karbon umumnya merepresentasikan…',opts:['Satu ton CO₂e yang berhasil dikurangi atau diserap','Satu kWh listrik terbarukan','Satu hektar hutan','Satu tahun operasi pabrik'],a:0,explain:'Kredit karbon distandarkan sebagai satu ton CO₂e yang terbukti dikurangi, dihindari, atau diserap dibanding skenario tanpa proyek. Standarisasi satuan inilah yang membuat kredit dari proyek berbeda bisa diperdagangkan.',hint:'Agar bisa diperdagangkan, satuannya harus seragam — dan satuan itu sama dengan satuan pelaporan emisi.'},
    {type:'pg',q:'Prinsip "additionality" dalam proyek kredit karbon berarti…',opts:['Penurunan emisi tidak akan terjadi tanpa adanya proyek tersebut','Proyek harus menambah jumlah karyawan','Proyek harus dibangun di lokasi baru','Kredit bisa dijual berkali-kali'],a:0,explain:'Additionality menuntut bukti bahwa penurunan emisi benar-benar terjadi karena proyek itu, bukan sesuatu yang toh akan terjadi secara bisnis biasa. Tanpa prinsip ini, kredit karbon tidak menghasilkan penurunan emisi nyata di atmosfer.',hint:'Ujilah dengan pertanyaan pengandaian: kalau proyeknya tidak ada, apakah penurunan itu tetap terjadi?'},
    {type:'pg',q:'Istilah "double counting" dalam pasar karbon adalah…',opts:['Satu penurunan emisi diklaim lebih dari satu pihak','Emisi dihitung dua kali setahun','Kredit dijual dengan harga ganda','Proyek diverifikasi dua auditor'],a:0,explain:'Double counting terjadi bila penurunan emisi yang sama diklaim oleh lebih dari satu pihak, misalnya oleh negara tuan rumah dan oleh pembeli kredit. Mekanisme registri dan corresponding adjustment dibangun justru untuk mencegah hal ini.',hint:'Masalahnya bukan pada penghitungan berulang, melainkan pada siapa yang mengaku berhak atas penurunan yang sama.'},
    {type:'pg',q:'Proses verifikasi kredit karbon oleh pihak ketiga independen bertujuan…',opts:['Memastikan klaim penurunan emisi benar, terukur, dan sesuai metodologi','Menaikkan harga kredit','Mempercepat penjualan kredit','Mengurangi pajak proyek'],a:0,explain:'Verifikasi independen memeriksa bahwa perhitungan penurunan emisi sesuai metodologi yang disetujui, datanya dapat ditelusuri, dan klaimnya wajar. Tanpa itu, kredit karbon tidak punya kredibilitas dan nilainya jatuh.',hint:'Pihak ketiga dilibatkan untuk menjawab keraguan tentang apa — kebenaran angkanya, atau kecepatan transaksinya?'},
    {type:'pg',q:'Perbedaan "carbon offset" dan "carbon reduction" pada strategi perusahaan adalah…',opts:['Reduction menurunkan emisi sendiri, offset mengimbangi dengan kredit dari pihak lain','Keduanya sama persis','Offset selalu lebih mahal daripada reduction','Reduction hanya berlaku untuk Scope 3'],a:0,explain:'Reduction berarti perusahaan benar-benar menurunkan emisinya sendiri, misalnya lewat efisiensi energi atau beralih ke energi terbarukan. Offset mengimbangi sisa emisi dengan membeli kredit dari proyek pihak lain, dan umumnya ditempatkan sebagai langkah terakhir setelah penurunan sendiri dimaksimalkan.',hint:'Satu mengubah apa yang terjadi di dalam perusahaan sendiri, satu lagi membeli hasil dari luar.'}
  ],

  // ===================================================================
  // S12 · EV & Charging Infrastructure Academy (kode 3L / 4L / 5L / 6L)
  // ===================================================================

  '3L.01': [
    {type:'pg',q:'Perbedaan utama BEV dan PHEV adalah…',opts:['BEV hanya bertenaga baterai, PHEV punya baterai yang bisa diisi dari luar sekaligus mesin bakar','BEV memakai bensin, PHEV tidak','PHEV tidak punya baterai','BEV tidak bisa diisi ulang'],a:0,explain:'BEV (Battery Electric Vehicle) sepenuhnya bertenaga baterai tanpa mesin bakar. PHEV (Plug-in Hybrid) punya baterai yang bisa diisi dari sumber listrik luar sekaligus mesin bakar sebagai penggerak cadangan atau tambahan.',hint:'Bedah singkatannya: huruf "B" menekankan satu sumber tenaga, sedangkan "PH" menandakan dua sumber ditambah kemampuan mengisi dari luar.'},
    {type:'pg',q:'FCEV (Fuel Cell Electric Vehicle) menghasilkan listrik penggeraknya dari…',opts:['Reaksi elektrokimia hidrogen dengan oksigen di sel bahan bakar','Pembakaran bensin di mesin','Panel surya di atap kendaraan','Pengereman regeneratif saja'],a:0,explain:'FCEV membawa hidrogen dalam tangki bertekanan, lalu sel bahan bakar mereaksikannya dengan oksigen udara menghasilkan listrik, dengan air sebagai hasil buangan. Motor listriknya sama seperti BEV, hanya sumber listriknya berbeda.',hint:'Nama "fuel cell" menunjuk pada reaksi kimia, bukan pembakaran. Bahan bakar apa yang dibawa kendaraan jenis ini?'},
    {type:'pg',q:'Keunggulan motor listrik dibanding mesin bakar untuk kendaraan adalah…',opts:['Torsi penuh tersedia sejak putaran nol dan efisiensinya jauh lebih tinggi','Suaranya lebih keras','Memerlukan lebih banyak perawatan berkala','Tidak memerlukan sistem pendingin sama sekali'],a:0,explain:'Motor listrik menghasilkan torsi maksimum sejak putaran nol sehingga akselerasinya responsif tanpa transmisi bertingkat, dengan efisiensi konversi di atas 85% dibanding sekitar 30% pada mesin bakar. Perawatannya juga lebih sedikit karena komponen bergeraknya jauh lebih sedikit.',hint:'Bandingkan kurva torsi kedua penggerak pada putaran rendah, lalu bandingkan efisiensi konversi energinya.'},
    {type:'pg',q:'Istilah "regenerative braking" pada kendaraan listrik berarti…',opts:['Energi kinetik saat pengereman diubah kembali menjadi listrik untuk mengisi baterai','Rem bekerja otomatis tanpa pengemudi','Rem memakai tekanan udara','Baterai diganti saat mengerem'],a:0,explain:'Saat memperlambat kendaraan, motor listrik dioperasikan sebagai generator sehingga energi kinetik diubah menjadi listrik dan dikembalikan ke baterai, alih-alih terbuang jadi panas di kampas rem. Ini menambah jarak tempuh terutama di lalu lintas padat.',hint:'Kata "regenerative" menunjuk pada energi yang dipulihkan. Energi apa yang biasanya terbuang menjadi panas saat mengerem?'},
    {type:'pg',q:'Tantangan terbesar adopsi kendaraan listrik di Indonesia dari sisi infrastruktur adalah…',opts:['Ketersediaan dan sebaran stasiun pengisian yang belum merata','Kendaraan listrik tidak bisa dipakai di iklim tropis','Tidak ada motor listrik yang diproduksi','Listrik tidak tersedia di Indonesia'],a:0,explain:'Kepercayaan calon pembeli sangat dipengaruhi kemudahan mengisi daya di perjalanan. Sebaran stasiun pengisian yang belum merata menimbulkan kecemasan jarak tempuh, sehingga perluasan SPKLU menjadi prasyarat adopsi massal.',hint:'Pikirkan kekhawatiran paling umum calon pembeli: "kalau baterai habis di jalan, saya isi di mana?"'},
    {type:'pg',q:'Istilah "range anxiety" pada pengguna kendaraan listrik merujuk pada…',opts:['Kekhawatiran kehabisan daya sebelum menemukan tempat pengisian','Ketakutan terhadap kecepatan tinggi','Kekhawatiran harga jual kembali','Kekhawatiran suara mesin terlalu senyap'],a:0,explain:'Range anxiety adalah kecemasan bahwa sisa daya baterai tidak cukup sampai ke tujuan atau ke stasiun pengisian terdekat. Kecemasan ini ditekan dengan memperluas jaringan pengisian, menambah kapasitas baterai, dan menyediakan informasi ketersediaan SPKLU secara waktu nyata.',hint:'Terjemahkan harfiah: kecemasan tentang JARAK yang masih bisa ditempuh.'}
  ],

  '3L.03': [
    {type:'pg',q:'Keunggulan utama baterai LFP dibanding NMC untuk kendaraan listrik adalah…',opts:['Lebih stabil secara termal dan umur siklusnya lebih panjang','Kerapatan energinya jauh lebih tinggi','Bobotnya jauh lebih ringan','Tidak memerlukan BMS'],a:0,explain:'LFP (lithium iron phosphate) lebih tahan terhadap thermal runaway dan umumnya bertahan lebih banyak siklus, dengan bahan baku tanpa kobalt sehingga lebih murah. Kelemahannya adalah kerapatan energi lebih rendah, sehingga untuk jarak tempuh sama dibutuhkan bobot dan volume lebih besar.',hint:'Setiap kimia baterai punya pertukaran. Kalau LFP unggul di keamanan dan umur, di sisi mana ia kalah?'},
    {type:'pg',q:'Istilah "thermal runaway" pada baterai lithium-ion adalah…',opts:['Reaksi berantai yang memicu kenaikan suhu tak terkendali hingga kebakaran','Pendinginan berlebihan saat cuaca dingin','Pengisian daya yang terlalu lambat','Penurunan tegangan saat beban berat'],a:0,explain:'Thermal runaway terjadi ketika panas dari reaksi internal memicu reaksi berikutnya yang melepas lebih banyak panas lagi, sehingga suhu naik tak terkendali dan berujung kebakaran. Pencegahannya lewat BMS, sistem manajemen termal, dan pemisahan fisik antar-sel.',hint:'Kata "runaway" menandakan proses yang lepas kendali. Besaran apa yang saling memperkuat dirinya sendiri di sini?'},
    {type:'pg',q:'Fungsi BMS (Battery Management System) pada kendaraan listrik adalah…',opts:['Memantau tegangan, arus, dan suhu tiap sel serta menjaganya dalam batas aman','Mengubah AC menjadi DC saat pengisian','Menggerakkan roda kendaraan','Mengatur sistem audio kendaraan'],a:0,explain:'BMS memantau tegangan, arus, dan suhu pada tingkat sel, menyeimbangkan muatan antar-sel, memutus rangkaian saat kondisi berbahaya, dan mengestimasi SoC/SoH. Tanpa BMS, sel yang terlalu diisi atau terlalu dikosongkan cepat rusak dan berisiko terbakar.',hint:'Sebuah pack berisi ratusan sel yang tidak pernah persis sama. Siapa yang mengawasi agar tak satu pun melewati batas amannya?'},
    {type:'pg',q:'Kerapatan energi (energy density) baterai dinyatakan dalam satuan…',opts:['Wh/kg atau Wh/liter','Ampere per jam','Volt per sel','Ohm per meter'],a:0,explain:'Kerapatan energi menyatakan berapa banyak energi tersimpan per satuan massa (Wh/kg) atau per satuan volume (Wh/liter). Makin tinggi nilainya, makin jauh jarak tempuh untuk bobot atau ruang baterai yang sama.',hint:'Kata "kerapatan" selalu berarti sesuatu dibagi massa atau volume. Yang dibagi di sini adalah besaran apa?'},
    {type:'pg',q:'Teknologi solid state battery menjanjikan perbaikan terutama pada…',opts:['Keamanan dan kerapatan energi, karena elektrolit cair diganti padat','Harga yang langsung paling murah','Kemampuan bekerja tanpa pengisian','Penghapusan kebutuhan motor listrik'],a:0,explain:'Mengganti elektrolit cair yang mudah terbakar dengan elektrolit padat menekan risiko kebakaran sekaligus membuka peluang memakai anoda logam litium yang kerapatan energinya lebih tinggi. Tantangannya masih pada biaya produksi dan daya tahan antarmuka elektrolit.',hint:'Perhatikan bagian mana yang diganti dari cair menjadi padat, lalu pikirkan dua masalah apa yang diselesaikan penggantian itu.'},
    {type:'pg',q:'Istilah C-rate 2C pada baterai berarti baterai diisi atau dikosongkan…',opts:['Dengan arus dua kali kapasitas nominalnya, sehingga penuh atau habis dalam sekitar setengah jam','Dalam waktu dua jam','Pada tegangan dua kali lipat','Pada suhu dua derajat'],a:0,explain:'C-rate menyatakan arus relatif terhadap kapasitas: 1C mengosongkan baterai dalam sekitar satu jam, sehingga 2C berarti arusnya dua kali lipat dan waktunya sekitar setengah jam. Makin tinggi C-rate, makin besar panas dan tekanan pada sel.',calc:'Arus (A) = C-rate × Kapasitas (Ah)',hint:'Angka di depan huruf C adalah pengali terhadap kapasitas. Kalau arusnya dua kali lipat, waktunya jadi berapa kali?'}
  ],

  '4L.01': [
    {type:'pg',q:'Perbedaan mendasar pengisian AC dan DC pada kendaraan listrik terletak pada…',opts:['Pada AC konversi dilakukan on-board charger di kendaraan, pada DC konversi terjadi di luar kendaraan','Pengisian AC tidak memakai listrik','Pengisian DC hanya untuk sepeda listrik','Keduanya identik, hanya beda merek'],a:0,explain:'Baterai selalu menerima arus searah. Pada pengisian AC, penyearahan dilakukan on-board charger di dalam kendaraan sehingga dayanya terbatas oleh ukuran perangkat itu. Pada DC fast charging, penyearahan dilakukan di stasiun sehingga daya jauh lebih besar bisa langsung dialirkan ke baterai.',hint:'Baterai hanya menerima satu jenis arus. Pertanyaannya: perangkat pengubahnya ada di dalam mobil atau di stasiun?'},
    {type:'pg',q:'Konektor CCS2 yang banyak dipakai SPKLU di Indonesia berfungsi untuk…',opts:['Melayani pengisian AC dan DC dalam satu soket gabungan','Hanya melayani pengisian AC','Menghubungkan panel surya ke jaringan','Mengisi baterai telepon genggam'],a:0,explain:'CCS (Combined Charging System) menggabungkan pin AC Type 2 di bagian atas dengan dua pin DC berarus besar di bagian bawah, sehingga satu inlet kendaraan melayani pengisian lambat maupun cepat. Standar ini menjadi acuan umum SPKLU di Indonesia.',hint:'Kata "Combined" pada namanya menjelaskan sendiri apa yang digabungkan dalam satu soket.'},
    {type:'pg',q:'Pengisian DC fast charging umumnya dibatasi hingga sekitar 80% SoC dengan laju tinggi karena…',opts:['Di atas 80% arus harus diturunkan agar sel tidak rusak dan tidak terlalu panas','Baterai tidak bisa diisi di atas 80%','Regulasi melarang pengisian penuh','Kabel tidak mampu menahan arus'],a:0,explain:'Mendekati muatan penuh, tegangan sel naik dan risiko pelapisan litium bertambah, sehingga BMS menurunkan arus secara bertahap. Akibatnya pengisian dari 80% ke 100% memakan waktu hampir sama lamanya dengan dari 0% ke 80%.',hint:'Kurva pengisian tidak datar. Apa yang harus dilakukan BMS pada arus saat sel makin penuh, dan mengapa?'},
    {type:'pg',q:'Komponen utama yang membedakan SPKLU DC fast charging dari pengisian AC rumahan adalah…',opts:['Adanya penyearah daya besar dan sistem pendingin di dalam unit stasiun','Adanya panel surya di setiap stasiun','Tidak memerlukan sambungan ke jaringan listrik','Tidak memerlukan proteksi arus lebih'],a:0,explain:'Stasiun DC berisi penyearah dan konverter daya berkapasitas puluhan hingga ratusan kilowatt beserta sistem pendinginnya, plus proteksi dan komunikasi ke kendaraan. Karena itu kebutuhan daya, ruang, dan biayanya jauh di atas pengisian AC rumahan.',hint:'Kalau konversi AC ke DC dipindah dari mobil ke stasiun, perangkat apa yang harus ada di dalam stasiun — dan apa akibatnya pada panas?'},
    {type:'pg',q:'Pemasangan SPKLU berdaya besar memerlukan studi dampak jaringan terutama karena…',opts:['Beban besar yang mendadak dapat menurunkan tegangan dan membebani trafo distribusi','Stasiun menghasilkan listrik yang mengalir balik ke jaringan','Stasiun memerlukan frekuensi berbeda dari jaringan','Stasiun tidak memerlukan pembumian'],a:0,explain:'SPKLU cepat menarik daya besar dalam waktu singkat dan bisa bersamaan dengan beban puncak. Tanpa studi, sambungan baru berisiko membuat tegangan turun, trafo kelebihan beban, dan mutu daya di sekitarnya memburuk.',hint:'Pikirkan apa yang terjadi pada jaringan setempat saat beban ratusan kilowatt menyala dalam hitungan detik.'},
    {type:'pg',q:'Strategi smart charging bertujuan…',opts:['Mengatur waktu dan laju pengisian agar tidak menumpuk pada beban puncak jaringan','Mempercepat pengisian tanpa memedulikan kondisi jaringan','Menghapus kebutuhan meteran listrik','Mengisi baterai tanpa kabel'],a:0,explain:'Smart charging menggeser atau melandaikan pengisian ke jam beban rendah dan mengatur laju sesuai kapasitas jaringan yang tersedia. Hasilnya biaya listrik lebih murah bagi pengguna dan beban puncak jaringan tidak bertambah tajam.',hint:'Kata "smart" di sini berkaitan dengan KAPAN dan SEBERAPA CEPAT mengisi, bukan seberapa besar dayanya selalu.'}
  ],

  // ===================================================================
  // S13 · Waste to Energy Academy (kode 3N / 4N / 5N / 6N)
  // ===================================================================

  '3N.01': [
    {type:'pg',q:'Konsep Waste to Energy (WtE) adalah…',opts:['Mengolah sampah menjadi energi listrik atau panas sekaligus mengurangi volume timbunan','Menimbun sampah rapat-rapat tanpa pengolahan','Mengubah energi listrik menjadi sampah','Mengekspor sampah ke negara lain'],a:0,explain:'WtE mengubah kandungan energi dalam sampah menjadi listrik atau panas melalui pembakaran terkendali atau proses termal lain, sekaligus memangkas volume yang harus ditimbun hingga sekitar 90%. Manfaatnya ganda: energi dan pengurangan beban TPA.',hint:'Namanya menyebut dua hal: bahan bakunya dan hasilnya. Manfaat keduanya berjalan bersamaan.'},
    {type:'pg',q:'Posisi WtE dalam bauran energi terbarukan Indonesia adalah…',opts:['Diakui sebagai energi terbarukan karena memanfaatkan fraksi biomassa dalam sampah','Tidak pernah dihitung sebagai energi sama sekali','Hanya dihitung sebagai energi fosil','Dilarang oleh regulasi nasional'],a:0,explain:'Sampah kota mengandung fraksi biogenik seperti sisa makanan, kertas, dan kayu yang tergolong terbarukan, sehingga bagian energi dari fraksi itu diakui sebagai energi terbarukan. Fraksi plastik yang berasal dari fosil dihitung terpisah.',hint:'Sampah kota bukan satu bahan tunggal. Pikirkan bagian mana yang berasal dari makhluk hidup dan bagian mana dari minyak bumi.'},
    {type:'pg',q:'Pengurangan volume sampah yang dapat dicapai insinerasi WtE umumnya sekitar…',opts:['90% volume dan sekitar 70–75% massa','10% volume','Tidak mengurangi volume sama sekali','100% tanpa sisa'],a:0,explain:'Pembakaran menghilangkan fraksi organik dan air, menyisakan abu dasar dan abu terbang. Volume berkurang sekitar 90% dan massa sekitar 70–75%. Sisa abu tetap harus dikelola, sehingga WtE mengurangi tetapi tidak menghapus kebutuhan TPA.',hint:'Pembakaran tidak memusnahkan materi, hanya mengubah bentuknya. Karena itu angkanya tinggi, tetapi tidak mungkin seratus persen.'},
    {type:'pg',q:'Keuntungan WtE dibanding penimbunan terbuka dari sisi emisi adalah…',opts:['Mencegah lepasnya metana dari pembusukan sampah yang GWP-nya jauh di atas CO₂','Tidak menghasilkan emisi apa pun','Menghasilkan oksigen murni','Menghapus kebutuhan pengolahan air lindi'],a:0,explain:'Sampah organik yang membusuk tanpa oksigen di TPA melepaskan metana dengan GWP puluhan kali CO₂. Dengan dibakar terkendali, karbonnya lepas sebagai CO₂ yang dampak iklimnya jauh lebih kecil per satuan massa, sambil menghasilkan listrik.',hint:'Bandingkan gas yang keluar dari timbunan sampah yang membusuk dengan gas hasil pembakaran, lalu bandingkan GWP keduanya.'},
    {type:'pg',q:'Tantangan utama penerapan WtE untuk sampah kota di Indonesia adalah…',opts:['Kadar air sampah yang tinggi sehingga nilai kalornya rendah','Tidak adanya sampah yang bisa diolah','Suhu udara Indonesia terlalu rendah','Tidak ada teknologi insinerator di dunia'],a:0,explain:'Sampah kota Indonesia didominasi sisa makanan dengan kadar air tinggi, sehingga nilai kalornya rendah dan sebagian energi terpakai hanya untuk menguapkan air. Karena itu pemilahan, pengeringan, atau pencampuran dengan sampah berkalori tinggi menjadi penting.',hint:'Pikirkan komposisi sampah dapur di Indonesia, lalu tanyakan berapa banyak energi terpakai untuk menguapkan kandungan airnya.'},
    {type:'pg',q:'Istilah PSEL dalam kebijakan persampahan Indonesia merujuk pada…',opts:['Pengolahan Sampah menjadi Energi Listrik','Pusat Sertifikasi Energi Listrik','Perusahaan Swasta Energi Lokal','Program Subsidi Energi Listrik'],a:0,explain:'PSEL adalah singkatan Pengolahan Sampah menjadi Energi Listrik, istilah resmi yang dipakai dalam kebijakan percepatan pembangunan instalasi pengolah sampah berbasis teknologi di sejumlah kota. Istilah ini bersanding dengan PLTSa di tingkat pembangkitnya.',hint:'Uraikan tiap hurufnya sebagai frasa Indonesia yang menggambarkan alur dari bahan baku ke hasil.'}
  ],

  '4N.01': [
    {type:'pg',q:'Prinsip 3T dalam desain ruang bakar insinerator adalah…',opts:['Time, Temperature, Turbulence','Tekanan, Tegangan, Torsi','Total, Tetap, Terukur','Timbang, Tuang, Tutup'],a:0,explain:'Pembakaran sempurna menuntut waktu tinggal gas yang cukup (time), suhu yang memadai (temperature), dan pencampuran yang baik antara gas dan udara (turbulence). Bila salah satu kurang, muncul CO dan senyawa organik tak terbakar.',hint:'Ketiganya dimulai huruf T dalam bahasa Inggris dan semuanya menggambarkan kondisi di dalam ruang bakar.'},
    {type:'pg',q:'Untuk menekan pembentukan dioksin, gas buang insinerator sampah umumnya harus dipertahankan pada suhu minimal…',opts:['850 °C selama sekurang-kurangnya 2 detik','200 °C selama 10 detik','50 °C selama 1 menit','1.500 °C selama 30 menit'],a:0,explain:'Persyaratan umum insinerasi sampah kota adalah gas buang mencapai minimal 850 °C dengan waktu tinggal sekurang-kurangnya 2 detik agar senyawa organik termasuk prekursor dioksin terurai. Pendinginan cepat setelahnya mencegah pembentukan ulang.',hint:'Angkanya adalah kombinasi suhu ratusan derajat dengan waktu tinggal hanya beberapa detik.'},
    {type:'pg',q:'Fungsi udara sekunder (secondary air) pada ruang bakar insinerator adalah…',opts:['Menambah turbulensi dan menyempurnakan pembakaran gas di atas tumpukan sampah','Mendinginkan abu dasar','Mengeringkan sampah sebelum masuk','Menggerakkan turbin uap'],a:0,explain:'Udara primer masuk dari bawah kisi untuk membakar tumpukan sampah, sedangkan udara sekunder diinjeksikan di atasnya untuk mengaduk dan menyempurnakan pembakaran gas yang terlepas. Tanpa udara sekunder, gas mudah lolos tanpa terbakar sempurna.',hint:'Dari dua aliran udara, yang satu menembus tumpukan bahan bakar. Yang lain bertugas di ruang mana, dan untuk apa?'},
    {type:'pg',q:'Istilah "excess air" dalam pembakaran sampah adalah…',opts:['Udara yang dipasok melebihi kebutuhan stoikiometri agar pembakaran sempurna','Udara yang bocor dari ruang bakar','Udara yang dipakai mendinginkan gedung','Udara yang keluar dari cerobong tanpa diolah'],a:0,explain:'Karena pencampuran tidak pernah sempurna, udara dipasok melebihi kebutuhan teoretis agar seluruh bahan bakar menemukan oksigen. Namun kelebihan yang berlebihan membuang energi karena ikut memanaskan nitrogen yang tidak berperan dalam pembakaran.',hint:'Kata "excess" berarti kelebihan terhadap suatu patokan. Patokan teoretisnya disebut apa, dan mengapa kelebihannya tidak boleh terlalu besar?'},
    {type:'pg',q:'Sistem grate (kisi) pada insinerator massa berfungsi…',opts:['Menahan dan membalik tumpukan sampah agar terbakar merata sambil dilewati udara primer','Menyaring gas buang sebelum ke cerobong','Menghasilkan listrik langsung','Mendinginkan uap dari boiler'],a:0,explain:'Moving grate menggerakkan dan membalik tumpukan sampah sepanjang ruang bakar sehingga proses pengeringan, pembakaran, dan pembakaran tuntas terjadi bertahap, sambil membiarkan udara primer menembus dari bawah. Ini teknologi paling lazim untuk sampah kota tanpa praolah.',hint:'Letaknya di dasar ruang bakar, tempat sampah bertumpuk. Dua tugasnya berkaitan dengan gerakan bahan dan aliran udara.'},
    {type:'pg',q:'Pada neraca massa insinerator, keluaran yang harus diperhitungkan meliputi…',opts:['Gas buang, abu dasar, abu terbang, dan residu sistem pengolah gas','Hanya gas buang saja','Hanya listrik yang dihasilkan','Hanya abu dasar saja'],a:0,explain:'Massa yang masuk sebagai sampah dan udara harus setara dengan seluruh keluaran: gas buang, abu dasar dari kisi, abu terbang yang tertangkap, serta residu dari sistem pengolah gas seperti kapur dan karbon aktif bekas. Melewatkan salah satunya membuat neraca tidak tertutup.',hint:'Massa tidak hilang. Daftar semua aliran yang KELUAR dari sistem, termasuk yang padat dan yang berasal dari bahan penolong.'}
  ],

  // ===================================================================
  // S14 · Hydrogen Energy Academy (kode 3O / 4O / 5O / 6O)
  // ===================================================================

  '3O.02': [
    {type:'pg',q:'Istilah "green hydrogen" merujuk pada hidrogen yang diproduksi melalui…',opts:['Elektrolisis air dengan listrik dari energi terbarukan','Reformasi gas alam tanpa penangkapan karbon','Gasifikasi batubara','Pemisahan dari udara bebas'],a:0,explain:'Green hydrogen dihasilkan dari elektrolisis air yang listriknya berasal dari sumber terbarukan seperti PLTS atau PLTB, sehingga emisi karbonnya mendekati nol. Reformasi gas alam tanpa penangkapan karbon menghasilkan grey hydrogen, dan dengan penangkapan karbon disebut blue hydrogen.',hint:'Warnanya ditentukan oleh sumber energi dan emisi prosesnya, bukan oleh warna gasnya — hidrogen selalu tak berwarna.'},
    {type:'pg',q:'Perbedaan blue hydrogen dan grey hydrogen terletak pada…',opts:['Blue hydrogen menangkap dan menyimpan CO₂ hasil prosesnya (CCS)','Blue hydrogen memakai air laut','Grey hydrogen diproduksi dari elektrolisis','Keduanya tidak menghasilkan CO₂'],a:0,explain:'Keduanya sama-sama dihasilkan dari bahan bakar fosil, umumnya lewat steam methane reforming. Bedanya, pada blue hydrogen CO₂ yang terbentuk ditangkap dan disimpan sehingga emisi yang lepas jauh berkurang, sedangkan pada grey hydrogen CO₂ dilepas ke atmosfer.',hint:'Kedua proses produksinya sama. Yang membedakan adalah nasib CO₂ setelah terbentuk.'},
    {type:'pg',q:'Sifat hidrogen yang paling menuntut perhatian khusus dalam penanganannya adalah…',opts:['Rentang campuran mudah terbakarnya sangat lebar dan energi penyalaannya sangat kecil','Hidrogen lebih berat dari udara sehingga mengendap','Hidrogen berbau menyengat sehingga mudah dideteksi','Hidrogen tidak bisa terbakar sama sekali'],a:0,explain:'Hidrogen mudah terbakar pada rentang konsentrasi sangat lebar (sekitar 4–75% di udara) dan hanya butuh energi penyalaan sangat kecil, sementara ia tidak berbau dan nyalanya nyaris tak terlihat. Karena lebih ringan dari udara, ia cepat naik, sehingga ventilasi di bagian atas ruangan sangat penting.',hint:'Pikirkan tiga hal sekaligus: seberapa lebar rentang campuran yang bisa menyala, seberapa kecil pemicu yang dibutuhkan, dan apakah indramu bisa mendeteksinya.'},
    {type:'pg',q:'Kerapatan energi hidrogen per satuan massa dibanding bensin adalah…',opts:['Sekitar tiga kali lebih besar per kilogram, tetapi jauh lebih kecil per liter','Lebih kecil per kilogram maupun per liter','Sama persis dengan bensin','Tidak bisa dibandingkan'],a:0,explain:'Hidrogen menyimpan sekitar 120 MJ/kg dibanding bensin sekitar 44 MJ/kg, jadi jauh unggul per satuan massa. Namun karena sangat ringan, per satuan volume ia kalah jauh, sehingga harus disimpan bertekanan tinggi atau dicairkan pada suhu sangat rendah.',hint:'Ada dua cara membandingkan: per kilogram dan per liter. Jawabannya berbeda arah untuk keduanya — itulah inti masalah penyimpanan hidrogen.'},
    {type:'pg',q:'Hidrogen untuk kendaraan FCEV umumnya disimpan dalam tangki bertekanan sekitar…',opts:['350–700 bar','1–2 bar','10 bar','5.000 bar'],a:0,explain:'Tangki FCEV umumnya bekerja pada 350 bar untuk bus dan truk atau 700 bar untuk mobil penumpang, agar jarak tempuh memadai dalam ruang terbatas. Tekanan sebesar ini menuntut tangki komposit dan protokol pengisian yang ketat.',hint:'Karena kerapatan energi per liternya rendah, tekanannya harus sangat tinggi — dalam ratusan, bukan satuan atau ribuan bar.'},
    {type:'pg',q:'Hasil buangan dari sel bahan bakar hidrogen adalah…',opts:['Air','Karbon dioksida','Sulfur dioksida','Abu padat'],a:0,explain:'Pada sel bahan bakar, hidrogen bereaksi dengan oksigen menghasilkan listrik, panas, dan air sebagai satu-satunya buangan di titik pemakaian. Jejak karbon keseluruhannya bergantung pada cara hidrogen itu diproduksi, bukan pada reaksi di selnya.',hint:'Tuliskan reaksi hidrogen dengan oksigen — senyawa apa yang terbentuk?'}
  ],

  '4O.02': [
    {type:'pg',q:'Konsumsi energi elektroliser modern untuk memproduksi hidrogen umumnya sekitar…',opts:['50–55 kWh per kilogram H₂','5 kWh per kilogram H₂','500 kWh per kilogram H₂','1 kWh per kilogram H₂'],a:0,explain:'Kebutuhan energi teoretis sekitar 39 kWh/kg, dan dengan efisiensi sistem nyata 70–80% kebutuhannya menjadi sekitar 50–55 kWh/kg. Angka ini menjadi penentu utama biaya produksi green hydrogen, karena biaya listrik mendominasi biaya operasinya.',hint:'Kebutuhan teoretisnya sekitar 39 kWh/kg; dengan efisiensi di bawah 100%, angka nyatanya bergeser ke arah mana?'},
    {type:'pg',q:'Perbedaan elektroliser alkaline dan PEM adalah…',opts:['PEM memakai membran polimer, lebih responsif terhadap beban berubah-ubah, tetapi lebih mahal','Alkaline tidak memerlukan listrik','PEM hanya bekerja pada suhu di atas 800 °C','Keduanya tidak menghasilkan oksigen'],a:0,explain:'Alkaline memakai elektrolit cair basa, teknologinya matang dan lebih murah, tetapi kurang lincah mengikuti beban yang naik-turun. PEM memakai membran penukar proton, responsnya cepat sehingga cocok dipadukan dengan PLTS atau PLTB yang fluktuatif, dengan biaya lebih tinggi karena memakai katalis logam mulia. SOEC-lah yang bekerja pada suhu sangat tinggi.',hint:'Kalau sumber listriknya matahari atau angin yang naik-turun, teknologi mana yang bisa mengikuti perubahan itu dengan cepat?'},
    {type:'pg',q:'Reaksi keseluruhan pada elektrolisis air menghasilkan…',opts:['Hidrogen di katoda dan oksigen di anoda','Hidrogen dan karbon dioksida','Oksigen saja','Metana dan air'],a:0,explain:'Elektrolisis memecah air menjadi hidrogen yang terbentuk di katoda (elektrode negatif) dan oksigen di anoda (elektrode positif), dengan perbandingan volume 2 banding 1. Oksigennya bernilai jual dan bisa dimanfaatkan, misalnya untuk kebutuhan industri atau medis.',hint:'Air tersusun dari dua unsur. Keduanya muncul kembali saat dipisahkan, masing-masing di elektrode yang berbeda.'},
    {type:'pg',q:'Untuk memproduksi 100 kg hidrogen per hari dengan konsumsi 55 kWh/kg, kebutuhan energi hariannya adalah…',opts:['5.500 kWh','550 kWh','55 kWh','55.000 kWh'],a:0,explain:'Kebutuhan energi dihitung 100 kg × 55 kWh/kg = 5.500 kWh per hari. Angka ini menunjukkan bahwa produksi hidrogen menuntut pasokan listrik besar, sehingga kelayakannya sangat bergantung pada harga listrik terbarukan.',calc:'Energi = Produksi (kg) × Konsumsi spesifik (kWh/kg)',hint:'Kalikan langsung kedua angka yang diberikan, lalu periksa jumlah nolnya dengan teliti.'},
    {type:'pg',q:'Air umpan untuk elektroliser harus dimurnikan terlebih dahulu karena…',opts:['Mineral terlarut merusak membran dan elektrode sehingga umur stack memendek','Air biasa tidak bisa dipecah menjadi hidrogen','Air murni menghasilkan hidrogen berwarna hijau','Regulasi melarang pemakaian air sumur'],a:0,explain:'Ion dan mineral terlarut mengendap pada membran serta meracuni katalis, menurunkan efisiensi dan memperpendek umur stack. Karena itu dipakai air terdeionisasi dengan konduktivitas sangat rendah, yang menambah kebutuhan sistem pengolahan air.',hint:'Pikirkan apa yang terjadi pada permukaan membran dan katalis bila ada mineral yang ikut mengendap terus-menerus.'},
    {type:'pg',q:'Balance of Plant (BoP) pada sistem elektrolisis mencakup…',opts:['Pengolahan air, pendinginan, pengeringan gas, kompresi, dan sistem kendali di luar stack','Hanya stack elektroliser itu sendiri','Hanya panel surya pemasok listrik','Hanya tangki penyimpanan hidrogen'],a:0,explain:'BoP adalah seluruh sistem pendukung di luar stack: pemurnian air, sirkulasi dan pendinginan elektrolit, pemisahan dan pengeringan gas, kompresi, serta kendali dan keselamatan. Porsi biayanya besar, sehingga tidak bisa diabaikan dalam perhitungan proyek.',hint:'Istilahnya berarti "sisa pabrik" — semua yang dibutuhkan agar komponen inti bisa bekerja.'}
  ],

  // ===================================================================
  // S15 · Battery & Energy Storage (BESS) Academy (kode 3P / 4P / 5P / 6P)
  // ===================================================================

  '3P.03': [
    {type:'pg',q:'State of Charge (SoC) sebuah baterai menyatakan…',opts:['Sisa muatan saat ini dibanding kapasitas maksimumnya, dalam persen','Umur baterai dalam tahun','Tegangan nominal sel','Arus maksimum yang boleh dialirkan'],a:0,explain:'SoC adalah persentase muatan tersisa terhadap kapasitas penuh baterai saat ini, sebanding dengan penunjuk bahan bakar pada kendaraan. Berbeda dengan SoH yang menyatakan kesehatan baterai dibanding kondisi barunya.',hint:'Analogikan dengan jarum bensin: yang ditunjuk adalah isi SEKARANG dibanding tangki penuh.'},
    {type:'pg',q:'State of Health (SoH) sebuah baterai menggambarkan…',opts:['Kapasitas baterai saat ini dibanding kapasitas ketika masih baru','Muatan yang tersisa hari ini','Suhu kerja baterai','Jumlah sel dalam satu pack'],a:0,explain:'SoH membandingkan kapasitas atau kemampuan baterai sekarang terhadap spesifikasi awalnya, sehingga menunjukkan tingkat penuaan. Baterai umumnya dianggap mencapai akhir masa pakai pada aplikasi awalnya ketika SoH turun ke sekitar 70–80%.',hint:'Bedakan dari SoC: yang satu berubah tiap jam, yang satu lagi berubah perlahan sepanjang tahun.'},
    {type:'pg',q:'Depth of Discharge (DoD) 80% berarti…',opts:['80% kapasitas baterai terpakai, menyisakan 20%','Baterai terisi 80%','Baterai rusak 80%','Efisiensi baterai 80%'],a:0,explain:'DoD menyatakan porsi kapasitas yang dikosongkan dalam satu siklus, jadi DoD 80% menyisakan SoC 20%. Membatasi DoD memperpanjang umur siklus baterai, sehingga strategi operasi BESS sering sengaja tidak mengosongkan baterai sampai habis.',hint:'DoD dan SoC adalah dua sisi yang saling melengkapi. Kalau dijumlahkan, berapa hasilnya?'},
    {type:'pg',q:'Efisiensi round-trip sebuah BESS menyatakan…',opts:['Perbandingan energi yang bisa dikeluarkan terhadap energi yang dimasukkan','Lama waktu pengisian penuh','Jumlah siklus sebelum rusak','Tegangan keluaran maksimum'],a:0,explain:'Round-trip efficiency membandingkan energi keluar terhadap energi masuk dalam satu siklus penuh isi-kosong, mencakup rugi di sel, konverter, dan sistem pendingin. Baterai litium modern umumnya mencapai 85–95%.',calc:'η_rt = Energi keluar ÷ Energi masuk × 100%',hint:'Kata "round-trip" menggambarkan perjalanan pulang-pergi energi: masuk lalu keluar lagi. Berapa yang tersisa sesampainya kembali?'},
    {type:'pg',q:'Kapasitas baterai 100 Ah pada tegangan 48 V setara dengan energi…',opts:['4,8 kWh','100 kWh','48 kWh','0,48 kWh'],a:0,explain:'Energi dihitung dengan mengalikan kapasitas muatan dan tegangan: 100 Ah × 48 V = 4.800 Wh = 4,8 kWh. Menyebut kapasitas hanya dalam Ah tanpa tegangan tidak cukup untuk membandingkan dua baterai.',calc:'Energi (Wh) = Kapasitas (Ah) × Tegangan (V)',hint:'Ah adalah satuan muatan, bukan energi. Besaran apa yang harus dikalikan agar menjadi Wh?'},
    {type:'pg',q:'Umur siklus (cycle life) baterai paling dipengaruhi oleh…',opts:['Kedalaman pengosongan, laju arus, dan suhu kerja','Warna casing baterai','Merek kabel penghubung','Jumlah tombol pada BMS'],a:0,explain:'Pengosongan yang dalam, arus tinggi, dan suhu kerja ekstrem mempercepat degradasi kimia di dalam sel. Karena itu strategi operasi BESS membatasi DoD, mengendalikan C-rate, dan menjaga suhu pada rentang optimal untuk memperpanjang umur aset.',hint:'Tiga faktor operasional yang bisa dikendalikan operator — semuanya berkaitan dengan seberapa keras baterai dipakai.'}
  ],

  '4P.01': [
    {type:'pg',q:'Fungsi cell balancing pada BMS adalah…',opts:['Menyamakan tingkat muatan antar-sel agar tidak ada sel yang kelebihan atau kekurangan','Menyamakan suhu ruangan','Menyeimbangkan beban antar-fasa jaringan','Menyamakan panjang kabel antar-modul'],a:0,explain:'Sel dalam satu pack tidak pernah persis identik, sehingga sebagian terisi lebih cepat. Tanpa penyeimbangan, kapasitas pack dibatasi sel terlemah dan sel terkuat berisiko kelebihan muatan. Balancing menyamakan kondisi antar-sel agar kapasitas dan keamanan terjaga.',hint:'Dalam rangkaian seri, satu sel yang lebih dulu penuh memaksa seluruh proses berhenti. Apa yang harus dilakukan terhadap perbedaan itu?'},
    {type:'pg',q:'Perbedaan passive balancing dan active balancing adalah…',opts:['Passive membuang kelebihan energi sel sebagai panas, active memindahkannya ke sel lain','Passive memerlukan listrik dari luar, active tidak','Active hanya bekerja saat baterai kosong','Keduanya tidak berbeda'],a:0,explain:'Passive balancing membuang kelebihan muatan sel yang lebih penuh melalui resistor sehingga energinya hilang sebagai panas — sederhana dan murah. Active balancing memindahkan energi dari sel penuh ke sel yang kurang, lebih efisien tetapi lebih rumit dan mahal.',hint:'Kata kuncinya adalah nasib energi berlebih: dibuang begitu saja, atau dipindahkan ke tempat yang membutuhkan?'},
    {type:'pg',q:'Proteksi yang wajib disediakan BMS mencakup…',opts:['Overvoltage, undervoltage, overcurrent, dan suhu berlebih','Hanya proteksi hubung singkat','Hanya proteksi petir','Hanya proteksi kelembapan'],a:0,explain:'BMS harus memutus atau membatasi operasi saat tegangan sel terlalu tinggi atau terlalu rendah, arus melebihi batas, dan suhu keluar dari rentang aman. Keempatnya adalah pemicu utama kerusakan permanen dan thermal runaway pada sel litium.',hint:'Daftar besaran yang dipantau BMS pada tiap sel, lalu pikirkan bahwa masing-masing punya batas atas dan batas bawah.'},
    {type:'pg',q:'Metode coulomb counting untuk estimasi SoC bekerja dengan cara…',opts:['Mengintegrasikan arus masuk dan keluar terhadap waktu','Mengukur suhu sel','Menghitung jumlah sel dalam pack','Mengukur tegangan jaringan'],a:0,explain:'Coulomb counting menjumlahkan muatan yang masuk dan keluar dengan mengintegrasikan arus terhadap waktu. Kelemahannya, galat kecil sensor arus terakumulasi seiring waktu, sehingga perlu dikalibrasi ulang dengan pembacaan tegangan saat istirahat.',calc:'SoC(t) = SoC₀ + (1/Kapasitas) ∫ I dt',hint:'Nama metodenya menyebut satuan muatan. Bagaimana cara memperoleh muatan dari pengukuran arus sepanjang waktu?'},
    {type:'pg',q:'Sistem manajemen termal pada BESS diperlukan karena…',opts:['Suhu terlalu tinggi mempercepat degradasi dan memicu risiko thermal runaway','Baterai tidak bisa bekerja di atas 0 °C','Suhu tidak memengaruhi baterai sama sekali','Pendinginan menambah kapasitas baterai secara permanen'],a:0,explain:'Laju reaksi penuaan di dalam sel meningkat tajam seiring suhu, dan pada titik tertentu bisa memicu reaksi berantai tak terkendali. Sistem manajemen termal menjaga seluruh sel berada dalam rentang suhu optimal sekaligus menyeragamkan suhu antar-sel.',hint:'Hubungkan suhu dengan dua hal sekaligus: kecepatan penuaan sel dan risiko keselamatan.'},
    {type:'pg',q:'Protokol komunikasi yang lazim dipakai BMS untuk berbicara dengan EMS atau inverter adalah…',opts:['CAN bus dan Modbus','HDMI dan VGA','USB audio','Bluetooth headset profile'],a:0,explain:'CAN bus banyak dipakai untuk komunikasi internal antar-modul baterai karena tahan derau dan bersifat waktu nyata, sedangkan Modbus lazim untuk berbicara dengan sistem manajemen energi dan SCADA. Keduanya adalah protokol industri, bukan protokol multimedia.',hint:'Cari protokol yang memang lahir dari dunia otomotif dan industri, bukan dari perangkat hiburan.'}
  ],

  // ===================================================================
  // S16 · Industrial Automation & Control Academy (kode 3Q / 4Q / 5Q / 6Q)
  // ===================================================================

  '3Q.01': [
    {type:'pg',q:'Perbedaan sistem kontrol loop terbuka dan loop tertutup adalah…',opts:['Loop tertutup memakai umpan balik hasil keluaran untuk mengoreksi aksi kendali','Loop terbuka selalu lebih akurat','Loop tertutup tidak memerlukan sensor','Loop terbuka memakai dua pengendali sekaligus'],a:0,explain:'Loop tertutup mengukur keluaran nyata dan membandingkannya dengan nilai acuan, lalu mengoreksi aksi kendali berdasarkan selisihnya. Loop terbuka bekerja tanpa memeriksa hasil, sehingga tidak bisa mengoreksi gangguan yang tidak diperhitungkan.',hint:'Pertanyaan pembedanya: apakah pengendali PERNAH memeriksa hasil kerjanya sendiri?'},
    {type:'pg',q:'Dalam piramida otomasi industri, urutan lapisan dari bawah ke atas adalah…',opts:['Field device → kontrol → supervisi → perencanaan perusahaan','Perencanaan perusahaan → field device → kontrol → supervisi','Kontrol → field device → perencanaan → supervisi','Supervisi → kontrol → perencanaan → field device'],a:0,explain:'Lapisan terbawah adalah perangkat lapangan (sensor dan aktuator), di atasnya lapisan kendali (PLC/DCS), lalu lapisan supervisi (SCADA/HMI), dan paling atas lapisan perencanaan perusahaan (MES/ERP). Makin ke atas, cakupannya makin luas tetapi kecepatan responsnya makin lambat.',hint:'Lapisan paling bawah adalah yang bersentuhan langsung dengan proses fisik; makin ke atas makin jauh dari mesin dan makin dekat ke keputusan bisnis.'},
    {type:'pg',q:'Yang dimaksud "setpoint" dalam sistem kendali adalah…',opts:['Nilai yang diinginkan untuk variabel proses yang dikendalikan','Nilai terukur saat ini','Batas maksimum peralatan','Waktu tunda pengendali'],a:0,explain:'Setpoint adalah nilai target yang ingin dicapai, misalnya suhu 80 °C. Nilai terukur saat ini disebut process variable, dan selisih keduanya disebut error yang menjadi masukan bagi pengendali.',hint:'Dari tiga istilah dasar (target, nilai terukur, selisihnya), yang mana yang ditetapkan manusia?'},
    {type:'pg',q:'Aktuator dalam sistem otomasi berfungsi…',opts:['Mengubah sinyal kendali menjadi aksi fisik seperti membuka katup atau memutar motor','Mengukur besaran proses','Menyimpan program kendali','Menampilkan data ke operator'],a:0,explain:'Aktuator adalah perangkat yang menjalankan perintah pengendali dalam bentuk gerakan atau perubahan fisik, misalnya katup kendali, motor, dan solenoid. Pengukuran dilakukan sensor, sedangkan penampilan data adalah tugas HMI.',hint:'Dari pasangan sensor dan aktuator, yang satu membaca keadaan dan yang satu lagi mengubahnya. Yang mana yang bertindak?'},
    {type:'pg',q:'Keunggulan utama PLC dibanding rangkaian relai konvensional adalah…',opts:['Logika kendali bisa diubah lewat pemrograman tanpa mengubah pengawatan','PLC tidak memerlukan catu daya','PLC tidak bisa rusak','PLC tidak memerlukan sensor'],a:0,explain:'Pada panel relai, mengubah logika berarti mengubah pengawatan secara fisik. Dengan PLC, logika berada dalam program sehingga perubahan cukup dilakukan lewat perangkat lunak, selain lebih ringkas, mudah didiagnosis, dan mampu menangani pewaktuan serta pencacahan kompleks.',hint:'Pikirkan pekerjaan yang harus dilakukan teknisi saat urutan kerja mesin perlu diubah pada kedua teknologi itu.'},
    {type:'pg',q:'Istilah "scan cycle" pada PLC menggambarkan…',opts:['Siklus berulang membaca masukan, menjalankan program, lalu memperbarui keluaran','Waktu pemanasan PLC saat dinyalakan','Jumlah sensor yang terpasang','Frekuensi tegangan catu daya'],a:0,explain:'PLC bekerja dalam siklus berulang: membaca status seluruh masukan, mengeksekusi program dari atas ke bawah, lalu memperbarui keluaran. Lama satu siklus (scan time) menentukan seberapa cepat sistem menanggapi perubahan di lapangan.',hint:'Runut tiga tahap yang dilakukan PLC berulang-ulang setiap saat, mulai dari membaca keadaan lapangan.'}
  ],

  '4Q.02': [
    {type:'pg',q:'Pada pengendali PID, peran komponen Integral adalah…',opts:['Menghilangkan galat tunak yang tersisa dengan menjumlahkan galat sepanjang waktu','Menanggapi laju perubahan galat','Memberi tanggapan sebanding dengan galat saat ini','Membatasi keluaran maksimum'],a:0,explain:'Komponen proporsional menanggapi besarnya galat saat ini tetapi biasanya menyisakan galat tunak. Komponen integral menjumlahkan galat sepanjang waktu sehingga sisa galat sekecil apa pun akhirnya terkoreksi, dengan risiko memperlambat dan menambah lonjakan bila terlalu besar.',hint:'Cocokkan tiap huruf dengan operasi matematikanya: yang satu sebanding, yang satu menjumlahkan sepanjang waktu, yang satu melihat laju perubahan.'},
    {type:'pg',q:'Komponen Derivative pada PID bekerja dengan…',opts:['Menanggapi laju perubahan galat sehingga meredam lonjakan','Menjumlahkan galat masa lalu','Menggandakan nilai setpoint','Mengukur suhu sekitar'],a:0,explain:'Komponen derivative memperhitungkan seberapa cepat galat berubah, sehingga memberi efek peredaman dan mengurangi overshoot. Kelemahannya, ia memperkuat derau pengukuran sehingga sering dipakai dengan penyaring atau bahkan dimatikan pada proses berderau.',hint:'Istilah "derivative" dalam matematika berarti turunan — turunan dari galat terhadap waktu menggambarkan apa?'},
    {type:'pg',q:'Gejala "overshoot" pada tanggapan sistem kendali adalah…',opts:['Variabel proses melewati setpoint sebelum akhirnya stabil','Variabel proses tidak pernah mencapai setpoint','Sensor berhenti membaca','Pengendali kehilangan catu daya'],a:0,explain:'Overshoot terjadi ketika variabel proses melampaui nilai acuan sebelum mengendap, biasanya akibat penguatan proporsional terlalu besar atau aksi integral berlebihan. Pada proses tertentu seperti pengendalian suhu tungku, overshoot bisa merusak produk.',hint:'Terjemahkan harfiah: "melewati tembakan" — melewati apa, sebelum akhirnya tenang?'},
    {type:'pg',q:'Istilah "integral windup" pada pengendali PID terjadi ketika…',opts:['Aksi integral terus menumpuk saat aktuator sudah mencapai batas maksimumnya','Sensor terbalik pemasangannya','Setpoint diubah terlalu sering','Catu daya PLC terlalu rendah'],a:0,explain:'Saat keluaran pengendali sudah menumbuk batas aktuator, galat tidak kunjung hilang sehingga suku integral terus menumpuk. Ketika kondisi berbalik, tumpukan itu perlu waktu lama untuk terurai sehingga tanggapan melonjak. Pencegahannya lewat anti-windup yang membekukan integrasi saat keluaran jenuh.',hint:'Pikirkan apa yang dilakukan suku integral saat katup sudah terbuka 100% tetapi galat masih ada.'},
    {type:'pg',q:'Sinyal analog 4–20 mA banyak dipakai di industri terutama karena…',opts:['Arus 4 mA sebagai nilai terendah membuat putusnya kabel bisa dideteksi','Lebih murah daripada sinyal digital','Tidak memerlukan catu daya','Bisa mengirim data video'],a:0,explain:'Karena batas bawahnya 4 mA dan bukan 0 mA, pembacaan 0 mA pasti menandakan kabel putus atau perangkat mati, bukan nilai proses nol. Sinyal arus juga kebal terhadap jatuh tegangan pada kabel panjang dan tahan derau.',hint:'Tanyakan mengapa rentangnya tidak dimulai dari nol. Apa yang bisa dibedakan berkat adanya batas bawah bukan-nol itu?'},
    {type:'pg',q:'Pada pemrograman ladder, instruksi timer TON (Timer On Delay) bekerja dengan…',opts:['Mengaktifkan keluaran setelah masukan menyala selama waktu yang ditentukan','Mengaktifkan keluaran seketika lalu mematikannya','Menghitung jumlah barang yang lewat','Menyimpan nilai analog ke memori'],a:0,explain:'TON mulai mencacah waktu ketika masukannya menyala, dan keluarannya baru aktif setelah waktu preset tercapai. Bila masukan mati sebelum waktu tercapai, pencacah kembali nol. Penghitungan jumlah barang adalah tugas instruksi counter.',hint:'Bedah namanya: "On Delay" berarti penundaan terjadi sebelum keluaran menyala, bukan sesudahnya.'}
  ]
};
